\label{ass:gaussian-cloud}
The training dataset consists of \((x_{i,s},i)\) for \(i\in[k]\) and \(s\in[n_i]\) such that
\begin{equation}
x_{i,s}:=\mu_i+r z_{i,s},
    \qquad\text{where}\qquad \mu_i\overset{\mathrm{iid}}{\sim}\mathcal N({\mathbf 0},I_d),\qquad z_{i,s}\overset{\mathrm{iid}}{\sim}\mathcal N({\mathbf 0},I_d).
\label{eq:gaussian-cloud}
\end{equation}
A test example \(X^{\mathrm{te}}\) with label \(Y\) is
\begin{equation}
X^{\mathrm{te}}:=\mu_Y+r_{\mathrm{te}}z^{\mathrm{te}},\qquad \mathbb P(Y=i)=\pi_{i,d},\qquad z^{\mathrm{te}}\sim\mathcal N({\mathbf 0},I_d),
\label{eq:population-test-model-clean}
\end{equation}
where \((\mu_i)_{i=1}^k\), \((z_{i,s})_{i,s}\), \(Y\), and \(z^{\mathrm{te}}\) are mutually independent. 
Here, \(r=r(d)\ge0\), \(r_{\mathrm{te}}=r_{\mathrm{te}}(d)>0\), \(\pi_{i,d}>0\), and \(\sum_{i=1}^k\pi_{i,d}=1\).

\label{ass:asymptotic-regime}
Along a sequence of models indexed by \(d\), with \(k=k(d)\), \(n_i=n_i(d)\), and \(\pi_{\min,d}:=\min_i\pi_{i,d}\),
\begin{equation}
k/d\to\alpha\in(0,\infty),\qquad n_{\min}\to\infty,\qquad \log N=o(d),\qquad \log(1/\pi_{\min,d})=o(d).
\label{eq:asymptotic-regime-clean}
\end{equation}
Furthermore, \(r_0:=\sup_d r(d)<\infty\) and \(r_{\mathrm{te},0}:=\sup_d r_{\mathrm{te}}(d)<\infty\).

\label{thm:det-optimizer-accuracy-order-clean}
Define the full-batch optimizer groups
\begin{equation}
\mathcal O_{\mathrm{row}}:=\{\mathrm{RowGD},\mathrm{RowGDM}\},\quad
\mathcal O_{\mathrm{comp}}:=\{\mathrm{SpecGD},\mathrm{Muon},\mathrm{SignGD},\mathrm{Signum},\mathrm{Adam}\}.
\label{eq:det-optimizer-groups}
\end{equation}
Suppose Assumptions~\ref{ass:gaussian-cloud}, \ref{ass:asymptotic-regime}, \ref{ass:adam-init}, \ref{ass:lr-base}, and~\ref{ass:lr-momentum} hold. Then, for every sufficiently large \(d\), with probability at least \(1-e^{-\sqrt d}\) over the training data, the following holds for all momentum parameters \(\beta \in (0,1)\) of RowGDM, Muon, and Signum:
\begin{equation}
\min_{\mathrm{opt}\in\mathcal O_{\mathrm{row}}}\liminf_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{opt}}\right)
>
\max_{\mathrm{opt}\in\mathcal O_{\mathrm{comp}}}\limsup_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{opt}}\right).
\label{eq:det-optimizer-accuracy-order-clean}
\end{equation}

\label{cor:det-optimizer-error-exponents}
Let \(\mathcal E_{t,d}^{\mathrm{opt}} := 1-\operatorname{Acc}_{\pi,d}(W_t^{\mathrm{opt}})\). 
Suppose Assumptions~\ref{ass:gaussian-cloud}, \ref{ass:asymptotic-regime}, \ref{ass:adam-init}, \ref{ass:lr-base}, and~\ref{ass:lr-momentum} hold. 
Then
\begin{align*}
\limsup_{t\to\infty}\left|\frac{r_{\mathrm{te}}^2}{d}\log \! \frac{\mathcal E_{t,d}^{\mathrm{Adam}}}{\mathcal E_{t,d}^{\mathrm{RowGDM}}}-\frac{\pi-2}{4\pi}\right|=o_{\mathbb P}(1), \ \ \
\liminf_{t\to\infty}\frac{r_{\mathrm{te}}^2}{d}\log \! \frac{\mathcal E_{t,d}^{\mathrm{Muon}}}{\mathcal E_{t,d}^{\mathrm{RowGDM}}}\ge\frac{1-\kappa_{\rm sp}(\alpha)^2}{4} \! - \!o_{\mathbb P}(1),
\end{align*}
where \(\kappa_{\rm sp}\) is the constant as in Proposition~\ref{prop:limiting-geometry}. 
The same conclusion holds with RowGDM replaced by RowGD, Adam by SignGD or Signum, and Muon by SpecGD.

\label{thm:stoch-optimizer-accuracy-order-clean}
Suppose Assumptions~\ref{ass:gaussian-cloud}, \ref{ass:asymptotic-regime}, \ref{ass:bounded-minibatches}, \ref{ass:lr-base}, and~\ref{ass:lr-momentum} hold. Then there exists \(\beta_0=\beta_0(\alpha,r_0,m_0)\in[0,1)\) such that, for every sufficiently large \(d\), with probability at least \(1-e^{-\sqrt d}\) over the training data, the following holds for all momentum parameters \(\beta \in [\beta_0,1)\) of RR-RowSGDM, RR-Muon, and RR-Signum, and for every realization of the reshuffling:
\begin{equation}
\liminf_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{RR\text{-}RowSGDM}}\right)
>
\max_{\mathrm{opt}\in\{\mathrm{RR\text{-}Muon},\,\mathrm{RR\text{-}Signum}\}}
\limsup_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{opt}}\right).
\label{eq:stoch-optimizer-accuracy-order-clean}
\end{equation}

\label{thm:rr-adamproxy-epoch-high-memory}
For each epoch \(r=0,1,2,\ldots\), let \(\tau_r:=mr\) denote the index of its first update and \(\gamma_r:=\sum_{s=0}^{m-1}\eta_{\tau_r+s}\) its total learning rate. Fix a training set with \(x_n[a]\neq0\) for all \(n\in[N]\) and \(a\in[d]\). 
Suppose that \(b<N\) and that Assumptions~\ref{ass:lr-base} and~\ref{ass:lr-momentum} hold. Then, for every \(\varepsilon>0\), RR-Adam in \eqref{eq:adam-update-clean} satisfies
\begin{equation}
\lim_{\substack{(\beta_1,\beta_2)\to(1,1)\\
0<\beta_1\le\beta_2<1}}
\limsup_{r\to\infty}
\mathbb P\left(
\left\|
\frac{W_{\tau_{r+1}}^{\mathrm{RR\text{-}Adam}}-W_{\tau_r}^{\mathrm{RR\text{-}Adam}}}{\gamma_r}
+\Phi_{N,b}\!\left(W_{\tau_r}^{\mathrm{RR\text{-}Adam}}\right)
\right\|_{\max}>\varepsilon
\right)=0,
\label{eq:rr-adamproxy-one-epoch-limit-clean}
\end{equation}
where the probability is over the random reshuffling.

\label{thm:adamproxy-optimizer-accuracy-order-clean}
Suppose Assumptions~\ref{ass:gaussian-cloud}, \ref{ass:asymptotic-regime}, \ref{ass:bounded-minibatches}, \ref{ass:lr-base}, and~\ref{ass:lr-momentum} hold. Then there exists \(\beta_1=\beta_1(\alpha,r_0,m_0)\in[0,1)\) such that, for every sufficiently large \(d\), with probability at least \(1-e^{-\sqrt d}\) over the training data, the following holds for all momentum parameters \(\beta\in[\beta_1,1)\) of RR-RowSGDM and for every realization of the reshuffling:
\begin{equation}
\liminf_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{RR\text{-}RowSGDM}}\right)
>
\limsup_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{AP}}\right).
\end{equation}

\label{ass:aniso-clean}
Let \(\Gamma,\Sigma_1,\ldots,\Sigma_k\) be positive-definite covariance matrices with \(\operatorname{tr}\Gamma=\operatorname{tr}\Sigma_i=d\) for every \(i\in[k]\).\footnote{A fixed trace preserves total variance while allowing covariance spectra and orientations to vary.} Training uses the clean class signals \(\{(\mu_i,i)\}_{i=1}^k\). A test example with label \(Y\) is \(X^{\mathrm{te}}:=\mu_Y+r_{\mathrm{te}}z^{\mathrm{te}}\), where, conditionally on the covariance matrices, \((Y,z^{\mathrm{te}})\) is independent of \((\mu_i)_{i=1}^k\) and
\begin{equation}
\mu_i\overset{\mathrm{iid}}{\sim}\mathcal N({\mathbf 0},\Gamma),\qquad
\mathbb P(Y=i)=\pi_{i,d}>0,\qquad
z^{\mathrm{te}}\mid Y\sim\mathcal N({\mathbf 0},\Sigma_Y).
\label{eq:aniso-training-model}
\end{equation}
Along the sequence indexed by \(d\), \(k/d\to\alpha\in(0,\infty)\) and \(r_{\mathrm{te}}>0\) satisfies \(r_{\mathrm{te},0}:=\sup_d r_{\mathrm{te}}(d)<\infty\).

\label{thm:aniso-dd-ordering}
Let \(\mathcal O_{\mathrm{row}}\) and \(\mathcal O_{\mathrm{comp}}\) be as in \eqref{eq:det-optimizer-groups}, with fixed \(\beta\in(0,1)\) for RowGDM, Muon, and Signum. Suppose Assumptions~\ref{ass:aniso-clean}, \ref{ass:adam-init}, \ref{ass:lr-base}, and~\ref{ass:lr-momentum} hold, with the covariances in \eqref{eq:aniso-covariances} for \(0\le s_\mu<1\) and \(s_\Sigma\ge0\). Assume that \(\log(1/\pi_{\min,d})=o(d/\log d)\) and that \(W_t^{\mathrm{opt}}/\|W_t^{\mathrm{opt}}\|_{\mathrm F}\) converges almost surely as \(t\to\infty\) for every \(\mathrm{opt}\in\mathcal O_{\mathrm{row}}\cup\mathcal O_{\mathrm{comp}}\). Then there exist constants \(c,C>0\), independent of \(d\), such that, for every sufficiently large \(d\), with probability at least \(1-Cd^{-c}\) over \(U_\mu\), \(O_1,\ldots,O_k\), and the class means,
\begin{equation}
\min_{\mathrm{opt}\in\mathcal O_{\mathrm{row}}}\liminf_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{opt}}\right)
>
\max_{\mathrm{opt}\in\mathcal O_{\mathrm{comp}}}\limsup_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{opt}}\right).
\label{eq:aniso-det-optimizer-ordering-clean-data}
\end{equation}

\label{lem:effective-margin-direction-convergence}
Suppose \(W_t\ne{\mathbf 0}\) eventually and, for some \(0\le\varepsilon<\gamma_\psi(X)\),
\begin{equation}
\liminf_{t\to\infty}\frac{\operatorname{mar}_X(W_t)}{\psi(W_t)}\ge\gamma_\psi(X)-\varepsilon.
\label{eq:app-effective-margin-convergence}
\end{equation}
Then
\begin{equation}
d_{\cos}(W_t,\mathcal U_{\psi,\varepsilon}^X)\longrightarrow0.
\label{eq:app-effective-direction-convergence}
\end{equation}

\label{lem:exact-margin-direction-convergence}
If
\begin{equation}
\frac{\operatorname{mar}_X(W_t)}{\psi(W_t)}\longrightarrow\gamma_\psi(X),
\label{eq:app-exact-margin-convergence}
\end{equation}
then
\begin{equation}
d_{\cos}(W_t,\mathcal U_\psi^X)\longrightarrow0.
\label{eq:app-exact-direction-convergence}
\end{equation}

\label{lem:app-general-lr-remainders}
Suppose Assumption~\ref{ass:lr-base} holds. Then \(S_t\to\infty\), and for every \(q>1\), \(c>0\), and fixed \(t_0\in\mathbb N\),
\begin{equation}
\frac{\sum_{s=0}^{t-1}\eta_s^q}{S_t}\longrightarrow0,\qquad \sum_{s=t_0}^{t-1}\eta_s\exp\!\left(-c\sum_{\tau=t_0}^{s-1}\eta_\tau\right)=O(1).
\label{eq:app-general-lr-remainders}
\end{equation}

\label{lem:app-general-lr-normalization}
Let \(\mathfrak m:\mathbb R^{k\times d}\to\mathbb R\) be continuous and positively homogeneous, let \(\Gamma_*:=\max_{\psi(W)\le1}\mathfrak m(W)>0\), and suppose \(0<\Gamma\le\Gamma_*\). Assume \(S_t\to\infty\). If
\[
\mathfrak m(W_t)\ge\Gamma S_t-r_t,\qquad \psi(W_t)\le C_0+S_t,\qquad r_t=o(S_t),
\]
then
\begin{equation}
\liminf_{t\to\infty}\frac{\mathfrak m(W_t)}{\psi(W_t)}\ge\Gamma.
\label{eq:app-general-lr-normalization}
\end{equation}
If \(\Gamma=\Gamma_*\), then \(\mathfrak m(W_t)/\psi(W_t)\to\Gamma_*\), and every accumulation point of \(W_t/\psi(W_t)\) maximizes \(\mathfrak m\) over the \(\psi\)-unit ball.

\label{lem:app-ms-basic}
Let \(\psi\) satisfy~\eqref{eq:app-ms-sandwich}, and let \(\psi^*\) be its dual norm. Then, for every matrix \(G\), every \(h\) with \(\|h\|_1\le R_1(X)\), and every \(A\in\mathbb R^{k\times d}\),
\begin{equation}
\psi^*(G)\le\|G\|_{\mathrm{sum}},\qquad \|Ah\|_\infty\le R_1(X)\psi(A).
\label{eq:app-ms-basic-bounds}
\end{equation}
Moreover, if \(s\in\mathbb R^k\) is a probability vector and \(H(s):=\operatorname{diag}(s)-ss^\top\), then for every \(c\in[k]\),
\begin{equation}
h^\top A^\top H(s)Ah\le4R_1(X)^2(1-s_c)\psi(A)^2.
\label{eq:app-ms-hessian}
\end{equation}

\label{thm:app-ms-full-batch}
Let \(\psi\) be max--sum dominated. Under Assumption~\ref{ass:lr-base}, normalized steepest descent
\begin{equation}
\Delta_t\in\operatorname*{arg\,max}_{\psi(\Delta)\le1}\langle\nabla L(W_t),\Delta\rangle,\qquad W_{t+1}=W_t-\eta_t\Delta_t
\label{eq:app-ms-nsd}
\end{equation}
satisfies
\begin{equation}
\frac{\operatorname{mar}_X(W_t)}{\psi(W_t)}\longrightarrow\gamma_\psi(X).
\label{eq:app-ms-nsd-margin}
\end{equation}
Under Assumptions~\ref{ass:lr-base} and~\ref{ass:lr-momentum}, the same conclusion holds for every fixed \(\beta\in(0,1)\) under normalized momentum descent with \(M_0={\mathbf 0}\):
\begin{equation}
M_{t+1}=\beta M_t+(1-\beta)\nabla L(W_t),\qquad
\Delta_t\in\operatorname*{arg\,max}_{\psi(\Delta)\le1}\langle M_{t+1},\Delta\rangle,
\qquad
W_{t+1}=W_t-\eta_t\Delta_t,
\label{eq:app-ms-nmd}
\end{equation}
In either case, every accumulation point of \(W_t/\psi(W_t)\) is a \(\psi\)-maximum-margin solution.

\label{thm:app-ms-full-batch-adam}
Consider full-batch Adam without bias correction or a numerical-stability constant, initialized by \(M_0=V_0={\mathbf 0}\):
\begin{align}
M_{t+1}&=\beta_1M_t+(1-\beta_1)\nabla L(W_t),\nonumber\\
V_{t+1}&=\beta_2V_t+(1-\beta_2)\nabla L(W_t)^{\odot2},\nonumber\\
W_{t+1}&=W_t-\eta_tM_{t+1}\oslash V_{t+1}^{\odot1/2}.
\label{eq:app-full-batch-adam}
\end{align}
Assume \(0<\beta_1\le\beta_2<1\), Assumptions~\ref{ass:lr-base} and~\ref{ass:lr-momentum}, and \(\min_{c\in[k],\,j\in[d]}|\nabla L(W_0)[c,j]|^2\ge\omega\) for some \(\omega>0\). Then, with
\[
\gamma_{\max}(X):=\max_{\|W\|_{\max}\le1}\operatorname{mar}_X(W),
\]
one has
\begin{equation}
\frac{\operatorname{mar}_X(W_t)}{\|W_t\|_{\max}}\longrightarrow\gamma_{\max}(X),
\label{eq:app-adam-margin}
\end{equation}
and every accumulation point of \(W_t/\|W_t\|_{\max}\) is a max-norm maximum-margin solution.

\label{lem:app-ga-atomic-package}
For every matrix norm \(\psi\), every sample \(x_n\), every matrix \(A\), and all classes \(a,c\in[k]\),
\begin{equation}
\|Ax_n\|_\infty\le R_\psi(X)\psi(A),\qquad \psi^*((e_a-e_c)x_n^\top)\le2R_\psi(X).
\label{eq:app-ga-logit-atom}
\end{equation}
For every \(W\),
\begin{equation}
\gamma_\psi(X)\mathcal G(W)\le\psi^*(\nabla L(W))\le2R_\psi(X)\mathcal G(W).
\label{eq:app-ga-gradient-proxy}
\end{equation}
For every sample \(n\), every \(W\), and every perturbation \(A\),
\begin{equation}
D^2\ell_n(W)[A,A]\le4R_\psi(X)^2\bigl(1-{\mathbb{S}}(Wx_n)_{y_n}\bigr)\psi(A)^2.
\label{eq:app-ga-hessian}
\end{equation}
Moreover, for all \(U,W\),
\begin{equation}
|L(U)-L(W)|\le2R_\psi(X)\psi(U-W).
\label{eq:app-ga-loss-lipschitz}
\end{equation}

\label{lem:app-ga-stability-package}
For \(U,W\in\mathbb R^{k\times d}\), define \(h:=R_\psi(X)\psi(U-W)\). Then, for every sample \(n\) and class \(c\),
\begin{equation}
e^{-2h}\le\frac{p_{n,c}(U)}{p_{n,c}(W)}\le e^{2h},\qquad e^{-2h}\le\frac{1-p_{n,y_n}(U)}{1-p_{n,y_n}(W)}\le e^{2h}.
\label{eq:app-ga-softmax-ratios}
\end{equation}
Consequently,
\begin{equation}
\mathcal G(U)\le e^{2R_\psi(X)\psi(U-W)}\mathcal G(W),
\label{eq:app-ga-proxy-stability}
\end{equation}
\begin{equation}
\psi^*(\nabla L(U)-\nabla L(W))\le2R_\psi(X)\Bigl(e^{2R_\psi(X)\psi(U-W)}-1\Bigr)\mathcal G(W),
\label{eq:app-ga-full-gradient-stability}
\end{equation}
and, for every mini-batch \(B\),
\begin{equation}
\psi^*(\nabla L_B(U)-\nabla L_B(W))\le2mR_\psi(X)\Bigl(e^{2R_\psi(X)\psi(U-W)}-1\Bigr)\mathcal G(W).
\label{eq:app-ga-batch-gradient-stability}
\end{equation}

\label{lem:app-ga-batch-noise}
\label{lem:app-ga-frozen-rr}
For a mini-batch \(B\) of size \(b\), define \(\Xi_B(W):=\nabla L_B(W)-\nabla L(W)\). Then
\begin{equation}
\psi^*(\Xi_B(W))\le2(m-1)R_\psi(X)\mathcal G(W).
\label{eq:app-ga-batch-noise}
\end{equation}
Moreover, let \(\{B_t\}_{t\ge0}\) be any random-reshuffling sequence, so that \(B_{qm},\ldots,B_{qm+m-1}\) partition \([N]\) for every epoch \(q\), and define
\begin{equation}
E_t(W):=(1-\beta)\sum_{\tau=0}^t\beta^\tau\bigl(\nabla L_{B_{t-\tau}}(W)-\nabla L(W)\bigr).
\label{eq:app-ga-frozen-ema}
\end{equation}
Then, deterministically for every reshuffling realization,
\begin{equation}
\psi^*(E_t(W))\le(1-\beta)m(m^2-1)R_\psi(X)\mathcal G(W).
\label{eq:app-ga-frozen-rr-bound}
\end{equation}

\label{prop:app-ga-momentum-approximation}
\label{prop:app-ga-descent-recurrence}
Assume Assumptions~\ref{ass:lr-base} and~\ref{ass:lr-momentum}. For every fixed finite dataset, fixed matrix norm \(\psi\), and fixed \(\beta\in(0,1)\), there exist \(t_{0,\psi,\beta}<\infty\) and \(c_{\psi,\beta}<\infty\) such that, for all \(t\ge t_{0,\psi,\beta}\),
\begin{align}
\psi^*(M_{t+1}-\nabla L(W_t))\le\Bigl[&2m(1-\beta)R_\psi(X)c_{\psi,\beta}\eta_t+(1-\beta)m(m^2-1)R_\psi(X)\nonumber\\
&+2R_\psi(X)\beta^{t+1}\Bigr]\mathcal G(W_t).
\label{eq:app-ga-momentum-approximation}
\end{align}
Define
\begin{equation}
\rho_{\psi,\beta,b}(X):=\gamma_\psi(X)-2(1-\beta)m(m^2-1)R_\psi(X),
\label{eq:app-ga-effective-margin}
\end{equation}
\begin{equation}
C_{\psi,\beta,b}:=4m(1-\beta)R_\psi(X)c_{\psi,\beta}+2R_\psi(X)^2e^{2R_\psi(X)\eta_0},\qquad D_\psi:=4R_\psi(X).
\label{eq:app-ga-descent-constants}
\end{equation}
Then, for all sufficiently large \(t\),
\begin{equation}
L(W_{t+1})\le L(W_t)-\eta_t\Bigl(\rho_{\psi,\beta,b}(X)-C_{\psi,\beta,b}\eta_t-D_\psi\beta^{t/2}\Bigr)\mathcal G(W_t).
\label{eq:app-ga-descent-recurrence}
\end{equation}

\label{cor:app-ga-margin-transfer}
Under Assumptions~\ref{ass:lr-base} and~\ref{ass:lr-momentum}, suppose \(\rho_{\psi,\beta,b}(X)>0\). Then
\begin{equation}
\liminf_{t\to\infty}\frac{\operatorname{mar}_X(W_t)}{\psi(W_t)}\ge\rho_{\psi,\beta,b}(X).
\label{eq:app-ga-margin-conclusion}
\end{equation}
Consequently, with
\begin{equation}
\varepsilon_{\psi,\beta,b}(X):=2(1-\beta)m(m^2-1)R_\psi(X),
\label{eq:app-ga-epsilon}
\end{equation}
one has
\begin{equation}
d_{\cos}\!\left(W_t,\mathcal U_{\psi,\varepsilon_{\psi,\beta,b}(X)}^X\right)\longrightarrow0.
\label{eq:app-ga-direction-conclusion}
\end{equation}
More quantitatively, there exist a finite \(t_2\) and \(C_{\mathrm{ga}}<\infty\) such that
\begin{equation}
\rho_{\psi,\beta,b}(X)-\frac{\operatorname{mar}_X(W_t)}{\psi(W_t)}\le C_{\mathrm{ga}}\frac{\mathcal R_t^{\psi,\beta,b}}{S_t},
\label{eq:app-ga-general-lr-bound}
\end{equation}
where
\begin{align}
\mathcal R_t^{\psi,\beta,b}:=&1+\sum_{s=0}^{t_2-1}\eta_s+C_{\psi,\beta,b}\sum_{s=t_2}^{t-1}\eta_s^2+\frac{D_\psi\eta_0}{1-\sqrt\beta}\nonumber\\
&+\sum_{s=t_2}^{t-1}\eta_s\exp\!\left(-\frac{\rho_{\psi,\beta,b}(X)}4\sum_{\tau=t_2}^{s-1}\eta_\tau\right).
\label{eq:app-ga-remainder}
\end{align}

\label{prop:app-row-steepest}
For every \(A,G\in\mathbb R^{k\times d}\),
\begin{equation}
\|A\|_{\max}\le\|A\|_{\mathrm{row}}\le\|A\|_{\mathrm{sum}},
\label{eq:app-row-max-sum}
\end{equation}
and
\begin{equation}
N_{\mathrm{row}}(G)\in\operatorname*{arg\,max}_{\|\Delta\|_{\mathrm{row}}\le1}\langle G,\Delta\rangle,\qquad \max_{\|\Delta\|_{\mathrm{row}}\le1}\langle G,\Delta\rangle=\sum_{r=1}^k\|G_{r,:}\|_2.
\label{eq:app-row-steepest}
\end{equation}
Thus row-wise normalized gradient methods are normalized steepest-descent methods for the row norm.

\label{cor:app-row-full-batch}
Consider any fixed linearly separable multiclass dataset with bounded features. Under Assumption~\ref{ass:lr-base}, row-wise normalized GD satisfies
\begin{equation}
\frac{\operatorname{mar}_X(W_t)}{\|W_t\|_{\mathrm{row}}}\longrightarrow\gamma_{\mathrm{row}}(X),\qquad \inf_{V\in\mathcal U_{\mathrm{row}}^X}\left\|\frac{W_t}{\|W_t\|_{\mathrm F}}-\frac{V}{\|V\|_{\mathrm F}}\right\|_{\mathrm F}\longrightarrow0.
\label{eq:app-row-gd-direction}
\end{equation}
If Assumption~\ref{ass:lr-momentum} also holds, the same two conclusions hold for row-wise normalized GD with every fixed momentum parameter \(\beta\in(0,1)\).

\label{cor:row-sgdm-rr-margin-clean}
Consider any fixed linearly separable multiclass dataset with bounded features. Run random-reshuffling row-wise normalized SGDM with \(b\mid N\), \(m:=N/b\), and fixed \(\beta\in(0,1)\). Define
\begin{equation}
R_{\mathrm{row}}(X):=\max_{n\in[N]}\|x_n\|_2,\qquad \varepsilon_{\mathrm{row},\beta,b}(X):=2(1-\beta)m(m^2-1)R_{\mathrm{row}}(X).
\label{eq:app-row-sgdm-epsilon}
\end{equation}
Under Assumptions~\ref{ass:lr-base} and~\ref{ass:lr-momentum}, if \(\varepsilon_{\mathrm{row},\beta,b}(X)<\gamma_{\mathrm{row}}(X)\), then
\begin{equation}
\liminf_{t\to\infty}\frac{\operatorname{mar}_X(W_t)}{\|W_t\|_{\mathrm{row}}}\ge\gamma_{\mathrm{row}}(X)-\varepsilon_{\mathrm{row},\beta,b}(X),
\label{eq:row-sgdm-rr-margin-clean}
\end{equation}
and
\begin{equation}
d_{\cos}\!\left(W_t,\mathcal U_{\mathrm{row},\varepsilon_{\mathrm{row},\beta,b}(X)}^X\right)\longrightarrow0.
\label{eq:row-sgdm-rr-direction-clean}
\end{equation}

\label{lem:app-common-rescaling}
Let \(c>0\), let \(cX:=\{(cx_n,y_n)\}_{n=1}^N\), and let \(\psi\) be any matrix norm. Then
\begin{equation}
\mathcal F_{cX}=c^{-1}\mathcal F_X,\qquad \mathcal M_\psi^{cX}=c^{-1}\mathcal M_\psi^X,\qquad \mathcal U_\psi^{cX}=\mathcal U_\psi^X.
\label{eq:app-common-rescaling}
\end{equation}
The normalized pairwise row directions and \(D_{\mathrm{avg\text{-}bdry}}\) are unchanged. If the test inputs are also multiplied by \(c\), then \(\operatorname{Acc}_{\pi,d}(c^{-1}W;cX^{\mathrm{te}})=\operatorname{Acc}_{\pi,d}(W;X^{\mathrm{te}})\).

\label{thm:deterministic-separation-clean}
Under Assumptions~\ref{ass:gaussian-cloud} and~\ref{ass:asymptotic-regime}, there are deterministic \(\omega_d\downarrow0\) and events \(\mathcal G_d^{\mathrm{det}}\) such that, for every sufficiently large \(d\),
\begin{equation}
\mathbb P(\mathcal G_d^{\mathrm{det}})\ge1-e^{-\sqrt d},
\label{eq:app-det-clean-probability}
\end{equation}
and, on \(\mathcal G_d^{\mathrm{det}}\), \(\mathcal F_X\ne\varnothing\) and
\begin{align}
\sup_{U\in\mathcal U_{\mathrm{row}}^X}\max_{i\ne j}\|u_{ij}^U-u_{ij}^{\mu}\|_2&\le\omega_d,
\label{eq:det-row-uniform-clean}\\
\sup_{U\in\mathcal U_{\mathrm{row}}^X}D_{\mathrm{avg\text{-}bdry}}(U)&\le\omega_d,
\label{eq:det-row-clean}\\
\inf_{U\in\mathcal U_{\mathrm{sp}}^X}D_{\mathrm{avg\text{-}bdry}}(U)&\ge\delta_{\mathrm{sp}}(\alpha)-\omega_d,
\label{eq:det-sp-clean}\\
\inf_{U\in\mathcal U_{\max}^X}D_{\mathrm{avg\text{-}bdry}}(U)&\ge\delta_{\max}-\omega_d.
\label{eq:det-max-clean}
\end{align}
Consequently, for every sufficiently large \(d\) on \(\mathcal G_d^{\mathrm{det}}\),
\begin{equation}
\sup_{U\in\mathcal U_{\mathrm{row}}^X}D_{\mathrm{avg\text{-}bdry}}(U)<\min\left\{\inf_{V\in\mathcal U_{\mathrm{sp}}^X}D_{\mathrm{avg\text{-}bdry}}(V),\inf_{V\in\mathcal U_{\max}^X}D_{\mathrm{avg\text{-}bdry}}(V)\right\}.
\label{eq:det-set-order-clean}
\end{equation}

\label{lem:app-det-ray-reduction}
For every $\psi\in\{\psi_{\mathrm{row}},\psi_{\mathrm{sp}},\psi_{\max}\}$,
\begin{align}
\sup_{U\in\mathcal U_\psi^X}D_{\mathrm{avg\text{-}bdry}}(U)
&=
\sup_{W\in\mathcal M_\psi^X}D_{\mathrm{avg\text{-}bdry}}(W),
\label{eq:app-det-ray-sup}\\
\inf_{U\in\mathcal U_\psi^X}D_{\mathrm{avg\text{-}bdry}}(U)
&=
\inf_{W\in\mathcal M_\psi^X}D_{\mathrm{avg\text{-}bdry}}(W).
\label{eq:app-det-ray-inf}
\end{align}

\label{prop:app-det-common-event}
Under Assumptions~\ref{ass:gaussian-cloud} and~\ref{ass:asymptotic-regime}, there are deterministic \(\varepsilon_d\downarrow0\), universal \(C<\infty\), a constant \(c=c(r_0)>0\), and events \(\mathcal E_d^{\mathrm{det}}\) such that
\begin{equation}
\mathbb P\!\left((\mathcal E_d^{\mathrm{det}})^c\right)\le C\exp\!\left[-c\sqrt{d\log(2N(d)(d+1))}\right]
\label{eq:app-det-common-event-probability}
\end{equation}
and the following statements hold simultaneously on \(\mathcal E_d^{\mathrm{det}}\):
\begin{enumerate}[label=(H\arabic*)]
\item \label{item:app-det-H1} \(\max_i\|m_i-\mu_i\|_2\le\varepsilon_d\).
\item \label{item:app-det-H2} \(\max_i|\|m_i\|_2-1|\le\varepsilon_d\) and \(\max_{i\ne j}|m_i^\top m_j|\le\varepsilon_d\).
\item \label{item:app-det-H3} \(\max_{i,j,s}|m_j^\top e_{i,s}|\le\varepsilon_d\).
\item \label{item:app-det-H4} \(\max_{i\ne j}\|u_{ij}^m-u_{ij}^{\mu}\|_2\le\varepsilon_d\).
\item \label{item:app-det-H5} The max-norm optimum is finite and satisfies
\begin{equation}
2\sqrt d\,r_{\max}^*(X)\le\sqrt{2\pi}+\varepsilon_d.
\label{eq:app-det-max-optimum-upper}
\end{equation}
\item \label{item:app-det-H6} Uniformly over ordered pairs,
\begin{equation}
\sup_{0\le\tau\le1}|H_{u_{ij}^m}(\tau)-A_{\max}(\tau)|+\sup_{0\le\tau\le1}|J_{u_{ij}^m}(\tau)-B_{\max}(\tau)|\le\varepsilon_d.
\label{eq:app-det-HJ-uniform}
\end{equation}
\end{enumerate}

\label{lem:app-det-normalization}
Let \(x,y\in\mathbb R^d\) with \(y\ne{\mathbf 0}\).
If \(\|x-y\|_2\le\|y\|_2/2\), then
\begin{equation}
\left\|\frac{x}{\|x\|_2}-\frac{y}{\|y\|_2}\right\|_2\le\frac{4\|x-y\|_2}{\|y\|_2}.
\label{eq:app-det-normalization-bound}
\end{equation}

\label{prop:app-det-row-rigidity}
Fix deterministic samples $x_{i,s}=m_i+e_{i,s}$ with $\sum_s e_{i,s}={\mathbf 0}$ for every $i$. Suppose that, for some $0<h<1/20$,
\begin{equation}
\max_i\bigl|\|m_i\|_2-1\bigr|\le h,
\qquad
\max_{i\ne j}|m_i^\top m_j|\le h,
\qquad
\max_{i,j,s}|m_j^\top e_{i,s}|\le h.
\label{eq:app-det-row-rigidity-assumption}
\end{equation}
Then $\mathcal F_X$ is nonempty, and every $W\in\mathcal M_{\mathrm{row}}^X$ satisfies
\begin{equation}
\max_i\|w_i-m_i\|_2
\le
C\left(h+\frac1k\right)^{1/4}
\label{eq:app-det-row-rigidity-conclusion}
\end{equation}
for a universal constant $C$.

For $i\ne j$ and $s\le n_i$,
\begin{align}
(m_i-m_j)^\top x_{i,s}
&=\|m_i\|_2^2-m_j^\top m_i+(m_i-m_j)^\top e_{i,s}
\notag\\
&\ge (1-h)^2-h-2h
\ge 1-5h.
\label{eq:app-det-row-witness-margin}
\end{align}
Hence the matrix with rows $\widetilde w_i=m_i/(1-5h)$ is feasible. If $R^*:=\max_i\|w_i\|_2$ is the optimal row radius, then
\begin{equation}
R^*\le\frac{1+h}{1-5h}\le1+Ch.
\label{eq:app-det-row-radius-upper}
\end{equation}

Let $\bar w:=k^{-1}\sum_{r=1}^k w_r$. For any feasible $W$, averaging the constraints over $s=1,\ldots,n_i$ and summing over $j\ne i$ gives
\begin{equation}
\sum_{j\ne i}(w_i-w_j)^\top m_i\ge k-1.
\label{eq:app-det-row-summed-constraints}
\end{equation}
Since $\sum_{j\ne i}w_j=k\bar w-w_i$, this is equivalent to
\begin{equation}
(w_i-\bar w)^\top m_i\ge1-\frac1k.
\label{eq:app-det-row-centering-constraint}
\end{equation}
Consequently,
\begin{equation}
\|w_i-\bar w\|_2
\ge
L:=\frac{1-1/k}{1+h}.
\label{eq:app-det-row-centered-lower}
\end{equation}
For a row-norm minimizer, the variance identity yields
\begin{align}
L^2
&\le
\frac1k\sum_{i=1}^k\|w_i-\bar w\|_2^2
=
\frac1k\sum_{i=1}^k\|w_i\|_2^2-\|\bar w\|_2^2
\le
(R^*)^2-\|\bar w\|_2^2.
\label{eq:app-det-row-variance-identity}
\end{align}
Combining this with \eqref{eq:app-det-row-radius-upper} gives
\begin{equation}
\|\bar w\|_2^2\le C\left(h+\frac1k\right).
\label{eq:app-det-row-common-shift-small}
\end{equation}
Using \eqref{eq:app-det-row-centering-constraint} once more,
\begin{equation}
w_i^\top m_i
\ge
1-\frac1k+\bar w^\top m_i
\ge
1-C\left(h+\frac1k\right)^{1/2}.
\label{eq:app-det-row-alignment-lower}
\end{equation}
Together with $\|w_i\|_2\le1+Ch$ and $\|m_i\|_2\le1+h$, this implies
\begin{align}
\|w_i-m_i\|_2^2
&=\|w_i\|_2^2+\|m_i\|_2^2-2w_i^\top m_i
\le
C\left(h+\frac1k\right)^{1/2}.
\label{eq:app-det-row-distance-square}
\end{align}
Taking square roots proves \eqref{eq:app-det-row-rigidity-conclusion}.

\label{prop:app-det-row-boundary}
Under \eqref{eq:gaussian-cloud}--\eqref{eq:asymptotic-regime-clean},
\begin{equation}
\sup_{W\in\mathcal M_{\mathrm{row}}^X}
D_{\mathrm{avg\text{-}bdry}}(W)
=o_{\mathbb P}(1).
\label{eq:app-det-row-boundary-convergence}
\end{equation}
In fact, the stronger uniform pairwise statement
\begin{equation}
\sup_{W\in\mathcal M_{\mathrm{row}}^X}
\max_{i\ne j}
\|u_{ij}^W-u_{ij}^{\mu}\|_2
=o_{\mathbb P}(1)
\label{eq:app-det-row-uniform-pair}
\end{equation}
holds.

Work on $\mathcal E_d^{\mathrm{det}}$ from Proposition~\ref{prop:app-det-common-event}. Apply Proposition~\ref{prop:app-det-row-rigidity} with $h=\varepsilon_d$. Since $k/d\to\alpha\in(0,\infty)$, we have $k\to\infty$, and therefore, uniformly over all row-norm minimizers,
\begin{equation}
\max_i\|w_i-m_i\|_2=o(1).
\label{eq:app-det-row-to-mean}
\end{equation}
Combining this with \ref{item:app-det-H1} gives
\begin{equation}
\Delta_d^{\mathrm{row}}
:=
\sup_{W\in\mathcal M_{\mathrm{row}}^X}
\max_i\|w_i-\mu_i\|_2
=o(1)
\label{eq:app-det-row-to-center}
\end{equation}
on $\mathcal E_d^{\mathrm{det}}$. Moreover, $\inf_{i\ne j}\|\mu_i-\mu_j\|_2$ is bounded below by a positive constant on the same event. Hence
\begin{equation}
\|(w_i-w_j)-(\mu_i-\mu_j)\|_2
\le2\Delta_d^{\mathrm{row}}
\label{eq:app-det-row-pair-perturbation}
\end{equation}
uniformly over $i\ne j$ and $W\in\mathcal M_{\mathrm{row}}^X$. Applying Lemma~\ref{lem:app-det-normalization} proves \eqref{eq:app-det-row-uniform-pair}, and averaging over ordered pairs gives \eqref{eq:app-det-row-boundary-convergence}.

\label{prop:app-det-clipped-exact}
Fix $u\in\mathbb S^{d-1}$ and $a,b>0$. Define
\begin{equation}
\mathfrak m_d(u;a,b)^2
:=
\min\left\{
\|x\|_2^2:
x^\top u\ge b,
\ \|x\|_\infty\le\frac{a}{\sqrt d}
\right\}.
\label{eq:app-det-clipped-problem}
\end{equation}
Let $z_\ell:=\sqrt d\,|u_\ell|$. If
\begin{equation}
0<b<a\frac1d\sum_{\ell=1}^d z_\ell,
\label{eq:app-det-clipped-feasibility}
\end{equation}
then the minimizer is unique and has coordinates
\begin{equation}
x_\ell
=
\frac{a}{\sqrt d}\operatorname{sign}(u_\ell)\min\{\tau z_\ell,1\},
\qquad
\ell=1,\ldots,d,
\label{eq:app-det-clipped-solution}
\end{equation}
where $\operatorname{sign}(0):=0$ and $\tau>0$ is the unique solution of
\begin{equation}
H_u(\tau)=\frac ba.
\label{eq:app-det-clipped-tau}
\end{equation}
Moreover,
\begin{equation}
\mathfrak m_d(u;a,b)^2=a^2J_u(\tau).
\label{eq:app-det-clipped-value}
\end{equation}

We first verify that the feasible set is nonempty. Define the coordinate-saturated vector $\widehat x\in\mathbb R^d$ by
\begin{equation}
\widehat x_\ell:=\frac{a}{\sqrt d}\operatorname{sign}(u_\ell).
\label{eq:app-det-clipped-saturated-vector}
\end{equation}
Its projection onto $u$ is
\begin{equation}
\widehat x^\top u
=
\frac{a}{\sqrt d}\sum_{\ell=1}^d|u_\ell|
=
\frac ad\sum_{\ell=1}^d z_\ell
>
b,
\label{eq:app-det-clipped-max-projection}
\end{equation}
where the strict inequality follows from \eqref{eq:app-det-clipped-feasibility}. Choose \(c\) such that \(b/(\widehat x^\top u)<c<1\). Then \(c\widehat x\) satisfies the projection constraint strictly and lies strictly inside the coordinate box. The feasible set is thus nonempty.
It is also closed and bounded, so a minimizer exists. Since the objective $x\mapsto\|x\|_2^2$ is strictly convex and the feasible set is convex, this minimizer is unique.

Let $x^\star$ denote the unique minimizer. We next show that every nonzero coordinate of $x^\star$ has the same sign as the corresponding coordinate of $u$. Given any feasible $x$, define $x^\sharp$ by
\begin{equation}
x^\sharp_\ell:=
\begin{cases}
\operatorname{sign}(u_\ell)|x_\ell|,&u_\ell\ne0,\\
0,&u_\ell=0.
\end{cases}
\label{eq:app-det-clipped-sign-alignment}
\end{equation}
Then $\|x^\sharp\|_\infty\le\|x\|_\infty$, $\|x^\sharp\|_2\le\|x\|_2$, and
\begin{equation}
(x^\sharp)^\top u
=
\sum_{\ell=1}^d|x_\ell||u_\ell|
\ge
\sum_{\ell=1}^d x_\ell u_\ell
=
x^\top u.
\label{eq:app-det-clipped-sign-projection}
\end{equation}
Applying this construction to $x^\star$ shows that $x^\sharp$ is feasible and has objective value no larger than that of $x^\star$. By optimality and uniqueness, $x^\star=x^\sharp$. Hence $x^\star_\ell$ has the sign of $u_\ell$ when $u_\ell\ne0$, and $x^\star_\ell=0$ when $u_\ell=0$.

The projection constraint must be active at the minimizer. Indeed, if $(x^\star)^\top u>b$, then
\begin{equation}
c:=\frac{b}{(x^\star)^\top u}
\end{equation}
satisfies $0<c<1$. The vector $cx^\star$ obeys $\|cx^\star\|_\infty\le a/\sqrt d$ and $(cx^\star)^\top u=b$, while
\begin{equation}
\|cx^\star\|_2^2=c^2\|x^\star\|_2^2<\|x^\star\|_2^2,
\end{equation}
contradicting the optimality of $x^\star$. Therefore,
\begin{equation}
(x^\star)^\top u=b.
\label{eq:app-det-clipped-active-projection}
\end{equation}

Because of the sign alignment, write
\begin{equation}
y_\ell:=\frac{\sqrt d}{a}|x^\star_\ell|,
\qquad
0\le y_\ell\le1.
\label{eq:app-det-clipped-y-definition}
\end{equation}
Using $|u_\ell|=z_\ell/\sqrt d$, the active projection constraint becomes
\begin{equation}
b
=
\sum_{\ell=1}^d|x^\star_\ell||u_\ell|
=
\frac ad\sum_{\ell=1}^d z_\ell y_\ell,
\end{equation}
or equivalently,
\begin{equation}
\sum_{\ell=1}^d z_\ell y_\ell=\frac{db}{a}.
\label{eq:app-det-clipped-reduced-constraint}
\end{equation}
Moreover,
\begin{equation}
\|x^\star\|_2^2
=
\frac{a^2}{d}\sum_{\ell=1}^d y_\ell^2.
\label{eq:app-det-clipped-reduced-objective}
\end{equation}
Therefore, finding $x^\star$ is equivalent to solving the convex optimization problem
\begin{equation}
\min_{0\le y_\ell\le1}
\frac12\sum_{\ell=1}^d y_\ell^2
\qquad
\text{subject to}
\qquad
\sum_{\ell=1}^d z_\ell y_\ell\ge\frac{db}{a}.
\label{eq:app-det-clipped-reduced-problem}
\end{equation}
The strict inequality in \eqref{eq:app-det-clipped-feasibility} implies that the right-hand side of the constraint is strictly smaller than $\sum_\ell z_\ell$, so the reduced problem has a strictly feasible point. Hence the KKT conditions are necessary and sufficient.

Let $\tau\ge0$ be the multiplier associated with the constraint in \eqref{eq:app-det-clipped-reduced-problem}. For fixed $\tau$, the Lagrangian minimization over the box $[0,1]^d$ separates across coordinates:
\begin{equation}
y_\ell
\in
\operatorname*{arg\,min}_{0\le y\le1}
\left\{
\frac12y^2-\tau z_\ell y
\right\}.
\label{eq:app-det-clipped-coordinate-kkt}
\end{equation}
The unconstrained minimizer of the scalar objective is $y=\tau z_\ell$. Projecting this value onto $[0,1]$ gives
\begin{equation}
y_\ell=\min\{\tau z_\ell,1\}.
\label{eq:app-det-clipped-y-solution}
\end{equation}
The multiplier must satisfy $\tau>0$. If $\tau=0$, then \eqref{eq:app-det-clipped-coordinate-kkt} gives $y_\ell=0$ for every $\ell$, which violates the constraint because $b>0$. Since $\tau>0$, complementary slackness implies that the projection constraint is active:
\begin{equation}
\sum_{\ell=1}^d z_\ell\min\{\tau z_\ell,1\}
=
\frac{db}{a}.
\label{eq:app-det-clipped-multiplier-equation}
\end{equation}
After dividing by $d$, this is exactly
\begin{equation}
H_u(\tau)
=
\frac1d\sum_{\ell=1}^d z_\ell\min\{\tau z_\ell,1\}
=
\frac ba.
\end{equation}

It remains to verify that this equation has a unique solution. The function $H_u$ is continuous and nondecreasing on $[0,\infty)$, with
\begin{equation}
H_u(0)=0,
\qquad
\lim_{\tau\to\infty}H_u(\tau)
=
\frac1d\sum_{\ell=1}^d z_\ell.
\label{eq:app-det-clipped-H-endpoints}
\end{equation}
The condition \eqref{eq:app-det-clipped-feasibility} places $b/a$ strictly between these two values, so existence follows from continuity. To prove uniqueness, take $0\le\tau_1<\tau_2$ and suppose that
\begin{equation}
H_u(\tau_1)<\frac1d\sum_{\ell=1}^d z_\ell.
\end{equation}
Then at least one coordinate with $z_\ell>0$ is not saturated at $\tau_1$, meaning $\tau_1z_\ell<1$. For that coordinate,
\begin{equation}
\min\{\tau_2z_\ell,1\}>\min\{\tau_1z_\ell,1\},
\end{equation}
while every other coordinate contributes a nondecreasing term. Thus $H_u(\tau_2)>H_u(\tau_1)$. Hence $H_u$ is strictly increasing before reaching its limiting value, and the equation $H_u(\tau)=b/a$ has a unique solution.

Substituting \eqref{eq:app-det-clipped-y-solution} into the sign-aligned representation of $x^\star$ gives
\begin{equation}
x^\star_\ell
=
\frac{a}{\sqrt d}\operatorname{sign}(u_\ell)\min\{\tau z_\ell,1\},
\end{equation}
which proves \eqref{eq:app-det-clipped-solution}. Finally,
\begin{align}
\mathfrak m_d(u;a,b)^2
&=
\|x^\star\|_2^2 \notag\\
&=
\frac{a^2}{d}\sum_{\ell=1}^d\min\{\tau z_\ell,1\}^2 \notag\\
&=
a^2\frac1d\sum_{\ell=1}^d\min\{\tau^2z_\ell^2,1\} \notag\\
&=
a^2J_u(\tau),
\end{align}
which proves \eqref{eq:app-det-clipped-value}.

\label{lem:app-det-clipped-asymptotic}
There exist constants $\delta_0,C_0>0$ such that the following holds. Suppose $u\in\mathbb S^{d-1}$ satisfies
\begin{equation}
\sup_{0\le\tau\le1}|H_u(\tau)-A_{\max}(\tau)|+\sup_{0\le\tau\le1}|J_u(\tau)-B_{\max}(\tau)|\le\delta
\label{eq:app-det-clipped-HJ-close}
\end{equation}
with $0<\delta\le\delta_0$, and suppose
\begin{equation}
|a-\sqrt{2\pi}|+|b-\sqrt2|\le\delta.
\label{eq:app-det-clipped-ab-close}
\end{equation}
Then \eqref{eq:app-det-clipped-feasibility} holds, the solution in Proposition~\ref{prop:app-det-clipped-exact} satisfies $\tau\in(0,1)$, and
\begin{align}
\frac1{\mathfrak m_d(u;a,b)}
&\le C_{\max}+C_0\delta,
\label{eq:app-det-clipped-reciprocal}\\
\frac b{\mathfrak m_d(u;a,b)}
&\le\kappa_{\max}+C_0\delta.
\label{eq:app-det-clipped-cosine}
\end{align}

Throughout the proof, $C>0$ denotes a constant independent of $d,u,a,b$, and $\delta$, and its value may change from line to line. Recall that $\tau_*>0$ is defined by
\begin{equation}
A_{\max}(\tau_*)=\frac1{\sqrt\pi}.
\label{eq:app-det-tau-star-recall}
\end{equation}
We first compare the required normalized projection $b/a$ with this reference value. By taking $\delta_0$ small enough, \eqref{eq:app-det-clipped-ab-close} ensures that $a\ge\sqrt{2\pi}/2$. Hence
\begin{align}
\left|\frac ba-\frac1{\sqrt\pi}\right|
&=
\left|\frac ba-\frac{\sqrt2}{\sqrt{2\pi}}\right| \notag\\
&\le
\frac{|b-\sqrt2|}{a}
+
\sqrt2\left|\frac1a-\frac1{\sqrt{2\pi}}\right| \notag\\
&=
\frac{|b-\sqrt2|}{a}
+
\frac{\sqrt2\,|a-\sqrt{2\pi}|}{a\sqrt{2\pi}}
\le C\delta.
\label{eq:app-det-clipped-ratio-close}
\end{align}
Thus the right-hand side of the equation $H_u(\tau)=b/a$ is within $O(\delta)$ of $A_{\max}(\tau_*)$.

We next show that the clipped problem is feasible and that its multiplier satisfies $\tau<1$. Since $\tau_*<1$ and $A_{\max}$ is strictly increasing, the constant
\begin{equation}
g_*:=A_{\max}(1)-A_{\max}(\tau_*)=A_{\max}(1)-\frac1{\sqrt\pi}
\label{eq:app-det-clipped-positive-gap}
\end{equation}
is strictly positive. By \eqref{eq:app-det-clipped-HJ-close},
\begin{equation}
H_u(1)\ge A_{\max}(1)-\delta=\frac1{\sqrt\pi}+g_*-\delta.
\label{eq:app-det-clipped-H-one-lower}
\end{equation}
On the other hand, \eqref{eq:app-det-clipped-ratio-close} gives
\begin{equation}
\frac ba\le\frac1{\sqrt\pi}+C\delta.
\label{eq:app-det-clipped-ratio-upper}
\end{equation}
After decreasing $\delta_0$ if necessary, these two bounds imply
\begin{equation}
0<\frac ba<H_u(1).
\label{eq:app-det-clipped-ratio-below-H-one}
\end{equation}
Because
\begin{equation}
H_u(1)=\frac1d\sum_{\ell=1}^d z_\ell\min\{z_\ell,1\}\le\frac1d\sum_{\ell=1}^d z_\ell,
\end{equation}
we obtain
\begin{equation}
0<b<a\frac1d\sum_{\ell=1}^d z_\ell.
\end{equation}
This is exactly \eqref{eq:app-det-clipped-feasibility}. Moreover, $H_u(0)=0$ and $H_u(1)>b/a$, so Proposition~\ref{prop:app-det-clipped-exact} gives a unique solution $\tau\in(0,1)$ of
\begin{equation}
H_u(\tau)=\frac ba.
\label{eq:app-det-clipped-solution-equation}
\end{equation}

We now show that this solution is close to $\tau_*$. Using \eqref{eq:app-det-clipped-solution-equation}, \eqref{eq:app-det-clipped-HJ-close}, \eqref{eq:app-det-clipped-ratio-close}, and \eqref{eq:app-det-tau-star-recall}, we obtain
\begin{align}
|A_{\max}(\tau)-A_{\max}(\tau_*)|
&\le
|A_{\max}(\tau)-H_u(\tau)|
+
\left|H_u(\tau)-A_{\max}(\tau_*)\right| \notag\\
&=
|A_{\max}(\tau)-H_u(\tau)|
+
\left|\frac ba-\frac1{\sqrt\pi}\right|
\le C\delta.
\label{eq:app-det-clipped-A-close}
\end{align}
For $s\in(0,1]$, differentiation under the expectation gives
\begin{equation}
A_{\max}'(s)=\mathbb E\left[G^2\mathbf{1}_{\{s|G|\le1\}}\right].
\label{eq:app-det-A-derivative}
\end{equation}
Since $s\le1$, the event $\{|G|\le1\}$ is contained in $\{s|G|\le1\}$. Therefore
\begin{equation}
A_{\max}'(s)\ge c_A,
\qquad
c_A:=\mathbb E\left[G^2\mathbf{1}_{\{|G|\le1\}}\right]>0.
\label{eq:app-det-A-derivative-lower}
\end{equation}
The mean value theorem and \eqref{eq:app-det-clipped-A-close} now give
\begin{equation}
c_A|\tau-\tau_*|
\le
|A_{\max}(\tau)-A_{\max}(\tau_*)|
\le C\delta,
\end{equation}
and hence
\begin{equation}
|\tau-\tau_*|\le C\delta.
\label{eq:app-det-clipped-tau-close}
\end{equation}

We next lower-bound $J_u(\tau)$. The first assumption of the lemma gives
\begin{equation}
J_u(\tau)\ge B_{\max}(\tau)-\delta.
\label{eq:app-det-clipped-J-first-lower}
\end{equation}
The function $B_{\max}$ is Lipschitz on $[0,1]$. Indeed, for $s,t\in[0,1]$,
\begin{align}
|B_{\max}(s)-B_{\max}(t)|
&\le
\mathbb E\left[\left|\min\{s^2G^2,1\}-\min\{t^2G^2,1\}\right|\right] \notag\\
&\le
|s^2-t^2|\mathbb E[G^2]
\le
2|s-t|.
\label{eq:app-det-B-Lipschitz}
\end{align}
Combining this bound with \eqref{eq:app-det-clipped-tau-close} gives
\begin{equation}
B_{\max}(\tau)\ge B_{\max}(\tau_*)-C\delta.
\end{equation}
Therefore,
\begin{equation}
J_u(\tau)\ge B_{\max}(\tau_*)-C\delta.
\label{eq:app-det-clipped-J-lower}
\end{equation}

The assumption on $a$ also gives
\begin{align}
a^2
&\ge
\left(\sqrt{2\pi}-\delta\right)^2
\ge
2\pi-C\delta.
\label{eq:app-det-clipped-a-square-lower}
\end{align}
Using the exact identity from Proposition~\ref{prop:app-det-clipped-exact},
\begin{equation}
\mathfrak m_d(u;a,b)^2=a^2J_u(\tau),
\end{equation}
together with \eqref{eq:app-det-clipped-J-lower} and \eqref{eq:app-det-clipped-a-square-lower}, we obtain
\begin{align}
\mathfrak m_d(u;a,b)^2
&\ge
(2\pi-C\delta)\left(B_{\max}(\tau_*)-C\delta\right) \notag\\
&\ge
2\pi B_{\max}(\tau_*)-C\delta.
\label{eq:app-det-clipped-energy-lower}
\end{align}

Set
\begin{equation}
M_*:=2\pi B_{\max}(\tau_*)>0.
\end{equation}
By taking $\delta_0$ smaller if necessary, \eqref{eq:app-det-clipped-energy-lower} implies
\begin{equation}
\mathfrak m_d(u;a,b)^2\ge M_*-C\delta\ge\frac{M_*}{2}.
\end{equation}
Consequently,
\begin{align}
\frac1{\mathfrak m_d(u;a,b)}
&\le
\frac1{\sqrt{M_*-C\delta}} \notag\\
&\le
\frac1{\sqrt{M_*}}+C\delta \notag\\
&=
C_{\max}+C\delta,
\label{eq:app-det-clipped-reciprocal-proof}
\end{align}
where the last equality follows from
\begin{equation}
C_{\max}=\left(2\pi B_{\max}(\tau_*)\right)^{-1/2}.
\end{equation}
After enlarging the constant, this proves \eqref{eq:app-det-clipped-reciprocal}.

Finally, \eqref{eq:app-det-clipped-ab-close} gives $b\le\sqrt2+\delta$. Therefore,
\begin{align}
\frac b{\mathfrak m_d(u;a,b)}
&\le
(\sqrt2+\delta)(C_{\max}+C_0\delta) \notag\\
&\le
\sqrt2\,C_{\max}+C\delta \notag\\
&=
\kappa_{\max}+C\delta,
\end{align}
because $\kappa_{\max}=\sqrt2\,C_{\max}$. Enlarging $C_0$ once more proves \eqref{eq:app-det-clipped-cosine}.

\label{prop:app-det-max-boundary}
Under \eqref{eq:gaussian-cloud}--\eqref{eq:asymptotic-regime-clean},
\begin{equation}
\inf_{W\in\mathcal M_{\max}^X}
D_{\mathrm{avg\text{-}bdry}}(W)
\ge\delta_{\max}-o_{\mathbb P}(1).
\label{eq:app-det-max-boundary-separation}
\end{equation}
In fact, on the same high-probability event, every ordered pair of every max-norm minimizer has boundary-normal distance at least $\delta_{\max}-o(1)$.

Work on $\mathcal E_d^{\mathrm{det}}$ from Proposition~\ref{prop:app-det-common-event}. Fix $W\in\mathcal M_{\max}^X$ and set $v_{ij}:=w_i-w_j$. By \ref{item:app-det-H5},
\begin{equation}
\|v_{ij}\|_\infty
\le2r_{\max}^*(X)
\le\frac{a_d}{\sqrt d},
\qquad
a_d:=\sqrt{2\pi}+\varepsilon_d.
\label{eq:app-det-max-pair-cap}
\end{equation}
Averaging the constraints $(w_i-w_j)^\top x_{i,s}\ge1$ over class $i$ gives $v_{ij}^\top m_i\ge1$. Applying the reverse constraints for class $j$ gives $v_{ij}^\top m_j\le-1$. Therefore
\begin{equation}
v_{ij}^\top(m_i-m_j)\ge2.
\label{eq:app-det-max-pair-projection}
\end{equation}
By \ref{item:app-det-H2}, uniformly over $i\ne j$,
\begin{equation}
\|m_i-m_j\|_2^2
=
\|m_i\|_2^2+\|m_j\|_2^2-2m_i^\top m_j
\le2+o(1).
\label{eq:app-det-mean-pair-norm-upper}
\end{equation}
Hence
\begin{equation}
v_{ij}^\top u_{ij}^m
\ge
\frac2{\|m_i-m_j\|_2}
\ge b_d,
\qquad
b_d:=\sqrt2-o(1),
\label{eq:app-det-max-unit-projection}
\end{equation}
where the error is deterministic on $\mathcal E_d^{\mathrm{det}}$ and uniform over all pairs.

Fix $i\ne j$, and abbreviate $u=u_{ij}^m$, $v=v_{ij}$, $a=a_d$, and $b=b_d$. Since $v^\top u\ge b>0$, define
\begin{equation}
y:=\frac b{v^\top u}v.
\label{eq:app-det-max-rescaled-pair}
\end{equation}
Then $y^\top u=b$, and because $b/(v^\top u)\le1$, \eqref{eq:app-det-max-pair-cap} gives $\|y\|_\infty\le a/\sqrt d$. Thus $y$ is feasible for \eqref{eq:app-det-clipped-problem}, and
\begin{equation}
\mathfrak m_d(u;a,b)
\le\|y\|_2
=
\frac{b\|v\|_2}{v^\top u}.
\label{eq:app-det-max-clipped-comparison}
\end{equation}
Equivalently,
\begin{equation}
\frac{v^\top u}{\|v\|_2}
\le
\frac b{\mathfrak m_d(u;a,b)}.
\label{eq:app-det-max-cosine-upper}
\end{equation}
By \ref{item:app-det-H6} and Lemma~\ref{lem:app-det-clipped-asymptotic}, the right-hand side is at most $\kappa_{\max}+o(1)$, uniformly over all ordered pairs. Since $\kappa_{\max}<1$,
\begin{equation}
\left\|
\frac{v_{ij}}{\|v_{ij}\|_2}-u_{ij}^m
\right\|_2
=
\sqrt{2-2\frac{v_{ij}^\top u_{ij}^m}{\|v_{ij}\|_2}}
\ge
\delta_{\max}-o(1).
\label{eq:app-det-max-away-from-empirical}
\end{equation}
Finally, \ref{item:app-det-H4} and the reverse triangle inequality imply
\begin{equation}
\left\|
\frac{v_{ij}}{\|v_{ij}\|_2}-u_{ij}^{\mu}
\right\|_2
\ge
\delta_{\max}-o(1),
\label{eq:app-det-max-away-from-bayes}
\end{equation}
uniformly over all pairs and all max-norm minimizers. Averaging proves \eqref{eq:app-det-max-boundary-separation}.

\label{lem:app-det-gaussian-critical-count}
Let $p=p(d)$ satisfy $p/d\to1$, let $H_d\in\mathbb R^{p\times d}$ have independent $\mathcal N(0,1)$ entries, and set $A_d:=H_d/\sqrt d$ and $n_d:=\min\{p,d\}$. There are universal constants $T,c,C>0$ such that, for all sufficiently large $d$ and every $2/n_d\le u\le T$, an event $\mathcal H_d(u)$ satisfies
\[
\mathbb P\bigl(\mathcal H_d(u)^c\bigr)\le C\bigl(1+\log(T/u)\bigr)e^{-cdu^2},
\]
and, on this event,
\begin{equation}
\frac1{n_d}\#\{\ell:\sigma_\ell(A_d)\le t\}\le8t,\qquad u\le t\le T.
\label{eq:app-det-gaussian-critical-count}
\end{equation}
Moreover, $A_d$ has rank $n_d$ almost surely.

\label{prop:app-det-spectral-input}
There are deterministic \(\eta_d\downarrow0\), constants \(c,C>0\), and events \(\mathcal E_d^{\mathrm{sp}}\) such that
\begin{equation}
\mathbb P\!\left((\mathcal E_d^{\mathrm{sp}})^c\right)\le C\exp\!\left[-c\sqrt{d\log(2N(d)(d+1))}\right]
\label{eq:app-det-spectral-event-probability}
\end{equation}
and the following statements hold on \(\mathcal E_d^{\mathrm{sp}}\):
\begin{enumerate}[label=(S\arabic*)]
\item \label{item:app-det-S1} \(C_m\) has rank \(r_d\), \(PQ_m=Q_m\), \(\|Q_m\|_{\mathrm{op}}=1\), and
\begin{equation}
\left|\frac{\|C_m\|_*}{k}-s_\alpha\right|\le\eta_d,\qquad \inf_{i\ne j}\|q_i-q_j\|_2\ge c_\alpha>0.
\label{eq:app-det-spectral-S1}
\end{equation}
\item \label{item:app-det-S2} Uniformly over \(i\ne j\),
\begin{equation}
\max_i\|m_i-\mu_i\|_2+\|\bar m\|_2\le\eta_d,\qquad \bar m:=\frac1k\sum_i m_i,
\label{eq:app-det-spectral-mean-inputs}
\end{equation}
\begin{equation}
\max_i|S_m[i,i]-s_\alpha|+\max_{i\ne j}|S_m[i,j]|\le\eta_d,\qquad \max_{i\ne j,s}|(q_i-q_j)^\top e_{i,s}|\le\eta_d.
\label{eq:app-det-spectral-entry-inputs}
\end{equation}
\item \label{item:app-det-S3} The reduced polar margin
\begin{equation}
\rho_X:=\min_{i\ne j,s}(q_i-q_j)^\top x_{i,s}
\label{eq:app-det-polar-margin-definition}
\end{equation}
satisfies
\begin{equation}
|\rho_X-s_\alpha|\le C\eta_d,\qquad \rho_X>0.
\label{eq:app-det-polar-feasible-margin}
\end{equation}
\item \label{item:app-det-S4} The reduced polar geometry satisfies
\begin{equation}
\left|D_{\mathrm{avg\text{-}bdry}}(Q_m)-\delta_{\mathrm{sp}}(\alpha)\right|\le\eta_d.
\label{eq:app-det-polar-uniform-gap}
\end{equation}
\item \label{item:app-det-S5} If \(\alpha\ne1\), all positive singular values of \(C_m\) lie in a deterministic compact interval bounded away from zero:
\begin{equation}
c_\alpha\le\sigma_{r_d}(C_m)\le\sigma_1(C_m)\le C_\alpha.
\label{eq:app-det-C0-extreme-singular-values}
\end{equation}
If \(\alpha=1\), there are \(t_0,C_0>0\) such that
\begin{equation}
\frac1{r_d}\#\{\ell:\sigma_\ell(C_m)\le t\}\le C_0(t+\eta_d),\qquad \eta_d\le t\le t_0.
\label{eq:app-det-critical-hard-count}
\end{equation}
\end{enumerate}

Because \(m_i=\mu_i+r\bar z_i\) is Gaussian with covariance \((1+r^2/n_i)I_d/d\), the rows are independent and admit the exact representation
\begin{equation}
M_m=D_dG/\sqrt d,\qquad D_d:=\operatorname{diag}\!\left(\sqrt{1+r^2/n_1},\ldots,\sqrt{1+r^2/n_k}\right),
\label{eq:app-det-gaussian-mean-matrix}
\end{equation}
where \(G\) has independent standard Gaussian entries.
Since \(\|D_d-I_k\|_{\mathrm{op}}\le Cr_0^2/n_{\min}=o(1)\) and \(\|G/\sqrt d\|_{\mathrm{op}}=O(1)\) with exponentially high probability, the comparator \(C_0:=PG/\sqrt d\) obeys
\begin{equation}
\|C_m-C_0\|_{\mathrm{op}}\le\zeta_d,\qquad \zeta_d\downarrow0.
\label{eq:app-det-Weyl-transfer}
\end{equation}
After a fixed orthogonal change of basis on \(\mathbb R^k\), the positive singular values of \(C_0\) have the same law as those of a \((k-1)\times d\) standard Gaussian matrix divided by \(\sqrt d\).
Marchenko--Pastur convergence therefore gives \(\|C_0\|_*/k\to s_\alpha\).
The normalized nuclear norm is \(O(d^{-1})\)-Lipschitz in the Gaussian entries, so Gaussian concentration and the deterministic expectation bias place this convergence under a deterministic envelope with failure probability bounded as in \eqref{eq:app-det-spectral-event-probability}.
The rank assertion is almost sure, and Weyl's inequality yields \eqref{eq:app-det-C0-extreme-singular-values} when \(\alpha\ne1\).

At $\alpha=1$, put $L_d:=\log(2N(d)(d+1))$ and $u_d:=(L_d/d)^{1/4}$. Then $u_d\to0$, $u_d\ge2/r_d$ eventually, and Lemma~\ref{lem:app-det-gaussian-critical-count} gives failure at most $C\exp(-c\sqrt{dL_d})$ after absorbing its logarithmic prefactor. Weyl's inequality and \eqref{eq:app-det-Weyl-transfer} transfer the count from $C_0$ to $C_m$ by replacing $t$ with $t+\zeta_d$. Enlarge the common envelope so that $\eta_d\ge\max\{u_d,\zeta_d\}$ and take $t_0<T/2$; then \eqref{eq:app-det-critical-hard-count} follows with precisely the probability scale in \eqref{eq:app-det-spectral-event-probability}.


Let \(S_0:=(C_0C_0^\top)^{1/2}\).
Conditionally on its singular values, the left singular frame of \(C_0\) is Haar in \(\mathbf{1}^\perp\) and independent of those singular values.
Haar concentration for the quadratic forms defining \(S_0[i,j]\), followed by a union bound over \(k^2\) entries, gives
\begin{equation}
\max_i\left|S_0[i,i]-\frac{\|C_0\|_*}{k}\right|+\max_{i\ne j}|S_0[i,j]|\le\chi_d,\qquad \chi_d\downarrow0.
\label{eq:app-det-S0-entry-concentration}
\end{equation}
The gap-free square-root inequality for positive semidefinite matrices gives
\begin{equation}
\|S_m-S_0\|_{\mathrm{op}}\le\|C_mC_m^\top-C_0C_0^\top\|_{\mathrm{op}}^{1/2}\le C\zeta_d^{1/2}.
\label{eq:app-det-gap-free-square-root}
\end{equation}
This proves the entrywise bounds in (S2) without dividing by the smallest singular value.
The empirical-mean bound is part of Proposition~\ref{prop:app-det-common-event}, and the Gaussian average \(k^{-1}\sum_i m_i\) gives \(\|\bar m\|_2=o(1)\) under the same probability envelope.

Conditionally on the empirical means, \(Q_m\) is deterministic and the residuals are centered Gaussian.
Since \(\|q_i-q_j\|_2\le\sqrt2\), Gaussian tails and a union bound over at most \(N^2\) indices give the residual bound in (S2).
Using that row \(i\) of \(C_m\) is \((m_i-\bar m)^\top\), we obtain
\begin{equation}
(q_i-q_j)^\top m_i=S_m[i,i]-S_m[j,i]+(q_i-q_j)^\top\bar m=s_\alpha+O(\eta_d).
\label{eq:app-det-polar-class-margin}
\end{equation}
Adding the residual bound proves (S3).
The same identity and \(\max_{i,s}\|x_{i,s}\|_2=O(1)\) give the uniform lower bound on \(\|q_i-q_j\|_2\).

It remains to identify the angular constant.
The centering identities \(\mathbf{1}^\top Q_m={\mathbf 0}\) and \(\|Q_m\|_{\mathrm F}^2=r_d\) give
\begin{equation}
\frac1{k(k-1)}\sum_{i\ne j}\|q_i-q_j\|_2^2=\frac{2r_d}{k-1}\longrightarrow\frac{2\rho_\alpha}{\alpha}.
\label{eq:app-det-polar-pair-average}
\end{equation}

If \(\alpha<1\), then \(r_d=k-1\) and \(Q_mQ_m^\top=P\), so every pair norm is exactly \(\sqrt2\). For \(\alpha>1\), let \(Q_0\) be the reduced polar factor of \(C_0\) and put \(\Pi_m:=Q_mQ_m^\top\) and \(\Pi_0:=Q_0Q_0^\top\). The left singular frame of \(C_0\), but not in general that of \(C_m=PD_dG/\sqrt d\), is Haar in \(\mathbf{1}^\perp\) when the class counts differ. The positive singular-value lower bounds and \eqref{eq:app-det-Weyl-transfer} give
\[
\|(I-\Pi_0)\Pi_m\|_{\mathrm{op}}\le\|C_m-C_0\|_{\mathrm{op}}\|C_m^\dagger\|_{\mathrm{op}}\le C_\alpha\zeta_d,
\]
and the analogous estimate with \(0\) and \(m\) exchanged. Consequently, \(\|\Pi_m-\Pi_0\|_{\mathrm{op}}\le C_\alpha\zeta_d\). Haar-projector concentration applies to \(\Pi_0\) and yields \((e_i-e_j)^\top\Pi_0(e_i-e_j)=2/\alpha+o(1)\) uniformly over pairs on the same probability scale. Since each such quadratic form changes by at most \(2\|\Pi_m-\Pi_0\|_{\mathrm{op}}\), we obtain \(\|q_i-q_j\|_2=\sqrt{2/\alpha}+o(1)\) uniformly. At \(\alpha=1\), no perturbation of the polar factor at the hard edge is needed for this step. The deterministic bounds \(\|q_i-q_j\|_2\le\sqrt2\) and \eqref{eq:app-det-polar-pair-average} give
\[
\frac1{k(k-1)}\sum_{i\ne j}\left|\|q_i-q_j\|_2-\sqrt2\right|
\le\frac1{\sqrt2}\left(2-\frac{2r_d}{k-1}\right)\longrightarrow0.
\]
Thus the required pair-norm convergence holds in averaged \(L^1\) at \(\alpha=1\).

Furthermore,
\begin{equation}
(q_i-q_j)^\top(\mu_i-\mu_j)=S_m[i,i]+S_m[j,j]-S_m[i,j]-S_m[j,i]+o(1)=2s_\alpha+o(1),
\label{eq:app-det-polar-cross-inner}
\end{equation}
while \(\|\mu_i-\mu_j\|_2=\sqrt2+o(1)\) uniformly.
Consequently, the pairwise cosine converges in averaged \(L^1\) to
\begin{equation}
\frac{2s_\alpha}{\sqrt{2\rho_\alpha/\alpha}\sqrt2}=\frac{m_{1/2}(\alpha)}{\sqrt{\rho_\alpha}}=\kappa_{\mathrm{sp}}(\alpha).
\label{eq:app-det-polar-cosine}
\end{equation}
Uniform continuity of \(x\mapsto\sqrt{2-2x}\) on \([-1,1]\) proves (S4).
Collecting the deterministic envelopes proves the proposition.

\label{lem:app-det-trace-truncation}
Let \(C=U\Sigma V^\top\) have rank \(r\), let \(Q=UV^\top\), and let \(B\) satisfy \(\|B\|_{\mathrm{op}}\le1\) and \(\operatorname{rank}(B)\le r\).
Put \(g_\ell:=u_\ell^\top Bv_\ell\) and \(a_\ell:=1-g_\ell\in[0,2]\).
Then
\begin{align}
\|B-Q\|_{\mathrm F}^2&\le2\sum_{\ell=1}^r a_\ell,
\label{eq:app-det-Frob-vs-trace}\\
\frac1r\sum_{\ell=1}^r a_\ell&\le2\frac{\#\{\ell:\sigma_\ell\le\tau\}}r+\frac1{\tau r}\sum_{\ell=1}^r\sigma_\ell a_\ell,\qquad \tau>0.
\label{eq:app-det-truncation}
\end{align}

\label{lem:app-det-average-normalization}
Let \(B,Q\in\mathbb R^{k\times d}\) have rows \(b_i,q_i\), suppose \(b_i-b_j\ne{\mathbf 0}\) for \(i\ne j\), and assume \(\inf_{i\ne j}\|q_i-q_j\|_2\ge c_0>0\).
If
\begin{equation}
E_2:=\frac1{k(k-1)}\sum_{i\ne j}\|(b_i-b_j)-(q_i-q_j)\|_2^2,
\label{eq:app-det-average-normalization-error}
\end{equation}
then
\begin{equation}
\frac1{k(k-1)}\sum_{i\ne j}\left\|\frac{b_i-b_j}{\|b_i-b_j\|_2}-\frac{q_i-q_j}{\|q_i-q_j\|_2}\right\|_2\le\frac4{c_0}E_2^{1/2}+\frac8{c_0^2}E_2.
\label{eq:app-det-average-normalization-bound}
\end{equation}

\label{prop:app-det-spectral-rigidity}
On the events of Proposition~\ref{prop:app-det-spectral-input}, let \(W\in\mathcal F_X\) satisfy
\begin{equation}
\|W\|_{\mathrm{op}}\le(1+\xi)r_{\mathrm{sp}}^*(X),\qquad 0\le\xi\le1.
\label{eq:app-det-near-spectral-assumption}
\end{equation}
Then
\begin{equation}
D_{\mathrm{avg\text{-}bdry}}(W)\ge\delta_{\mathrm{sp}}(\alpha)-\begin{cases}C_\alpha(\eta_d+\xi)^{1/2},&\alpha\ne1,\\ C(\eta_d+\xi)^{1/4},&\alpha=1.\end{cases}
\label{eq:app-det-near-spectral-bound}
\end{equation}
In particular, every exact minimizer satisfies
\begin{equation}
\frac1{r_d}\left\|\frac{PW}{\|PW\|_{\mathrm{op}}}-Q_m\right\|_{\mathrm F}^2\le\begin{cases}C_\alpha\eta_d,&\alpha\ne1,\\ C\sqrt{\eta_d},&\alpha=1,\end{cases}
\label{eq:app-det-spectral-frobenius-rigidity}
\end{equation}
uniformly over \(W\in\mathcal M_{\mathrm{sp}}^X\).

The polar witness \(Q_m/\rho_X\) is feasible, so
\begin{equation}
r_{\mathrm{sp}}^*(X)\le\rho_X^{-1}.
\label{eq:app-det-spectral-optimum-upper}
\end{equation}
For every feasible \(W\), summing the class-averaged constraints over ordered pairs gives
\begin{equation}
\langle PW,C_m\rangle\ge k-1.
\label{eq:app-det-spectral-dual-lower}
\end{equation}
Set \(A:=PW\), \(a:=\|A\|_{\mathrm{op}}>0\), and \(B:=A/a\).
Centering is an operator-norm contraction and preserves all row differences, while \(\operatorname{rank}(B)\le r_d\).
Equations \eqref{eq:app-det-spectral-optimum-upper}, \eqref{eq:app-det-spectral-dual-lower}, and Proposition~\ref{prop:app-det-spectral-input} give
\begin{equation}
\frac1{r_d}\sum_{\ell=1}^{r_d}\sigma_\ell(C_m)\left(1-u_\ell^\top Bv_\ell\right)\le C(\eta_d+\xi).
\label{eq:app-det-spectral-polar-inner-product}
\end{equation}
If \(\alpha\ne1\), the positive edge in \eqref{eq:app-det-C0-extreme-singular-values} and Lemma~\ref{lem:app-det-trace-truncation} yield \(r_d^{-1}\|B-Q_m\|_{\mathrm F}^2\le C_\alpha(\eta_d+\xi)\).
If \(\alpha=1\), set \(q:=\eta_d+\xi\) and use \(\tau=\sqrt q\) in \eqref{eq:app-det-truncation} together with \eqref{eq:app-det-critical-hard-count}; the result is
\begin{equation}
\frac1{r_d}\|B-Q_m\|_{\mathrm F}^2\le Cq^{1/2}.
\label{eq:app-det-critical-spectral-frobenius}
\end{equation}
The case of non-small \(q\) follows by increasing \(C\) and using the trivial bound.
Taking \(\xi=0\) proves \eqref{eq:app-det-spectral-frobenius-rigidity}.

Because both \(B\) and \(Q_m\) are centered,
\begin{equation}
\frac1{k(k-1)}\sum_{i\ne j}\|(b_i-b_j)-(q_i-q_j)\|_2^2=\frac{2}{k-1}\|B-Q_m\|_{\mathrm F}^2.
\label{eq:app-det-pairwise-Frobenius}
\end{equation}
Feasibility ensures \(b_i-b_j\ne{\mathbf 0}\), and Proposition~\ref{prop:app-det-spectral-input} supplies a uniform lower bound on the polar pair norms.
Lemma~\ref{lem:app-det-average-normalization}, followed by the reverse triangle inequality and \eqref{eq:app-det-polar-uniform-gap}, proves \eqref{eq:app-det-near-spectral-bound}.

\label{prop:app-det-spectral-boundary}
Under Assumptions~\ref{ass:gaussian-cloud} and~\ref{ass:asymptotic-regime},
\begin{equation}
\inf_{W\in\mathcal M_{\mathrm{sp}}^X}D_{\mathrm{avg\text{-}bdry}}(W)\ge\delta_{\mathrm{sp}}(\alpha)-o_{\mathbb P}(1).
\label{eq:app-det-spectral-boundary-separation}
\end{equation}
The bound holds on the events in Proposition~\ref{prop:app-det-spectral-input} with the deterministic error in \eqref{eq:app-det-near-spectral-bound} at \(\xi=0\).

\label{lem:app-acc-pairwise-gaussian}
For every \(i<j\), let \(e_{ij}(W):=\{p_{i\to j}(W)+p_{j\to i}(W)\}/2\). Then
\begin{equation}
\max_{i<j}\{\pi_{i,d}p_{i\to j}(W)+\pi_{j,d}p_{j\to i}(W)\}\le\mathcal E_{\pi,d}(W)\le\sum_{i<j}\{\pi_{i,d}p_{i\to j}(W)+\pi_{j,d}p_{j\to i}(W)\},
\label{eq:app-acc-weighted-sandwich}
\end{equation}
and hence \(\mathcal E_{\pi,d}(W)\ge2\pi_{\min,d}\max_{i<j}e_{ij}(W)\). Moreover, with \(c_{ij}(W):=1-d_{ij}(W)^2/2\),
\begin{equation}
e_{ij}(W)=\frac12\left[\overline\Phi\!\left(\frac{s_{ij}c_{ij}(W)/2+\langle u_{ij}^W,m_{ij}\rangle}{\sigma_d}\right)+\overline\Phi\!\left(\frac{s_{ij}c_{ij}(W)/2-\langle u_{ij}^W,m_{ij}\rangle}{\sigma_d}\right)\right]\ge\overline\Phi\!\left(\frac{s_{ij}(c_{ij}(W))_+}{2\sigma_d}\right),
\label{eq:app-acc-pairwise-midpoint-free}
\end{equation}
where \(\overline\Phi(a)=\mathbb P(Z\ge a)\) for \(Z\sim\mathcal N(0,1)\).

\label{lem:app-acc-gaussian-radial-event}
There are deterministic \(\eta_d\downarrow0\) and events \(\mathcal R_d\), depending only on the class means, such that, for every sufficiently large \(d\),
\begin{equation}
\mathbb P(\mathcal R_d^c)\le\frac14e^{-\sqrt d},\qquad \tau_d+\rho_d\le\eta_d\quad\text{on }\mathcal R_d.
\label{eq:app-acc-radial-event-probability}
\end{equation}

\label{prop:app-acc-finite-bounds}
If \(A_d>0\), then
\begin{equation}
\sup_{W\in\mathcal R_d^{\mathrm{clf}}}\mathcal E_{\pi,d}(W)\le(k-1)\overline\Phi\!\left(\frac{A_d}{\sigma_d}\right),\qquad \inf_{W\in\mathcal C_d^{\mathrm{clf}}}\mathcal E_{\pi,d}(W)\ge2\pi_{\min,d}\overline\Phi\!\left(\frac{B_d}{\sigma_d}\right).
\label{eq:app-acc-finite-bounds}
\end{equation}

\label{thm:app-acc-transfer}
Suppose \(\tau_d+\rho_d\to0\), \(\limsup_d h_d\le\overline h\), and \(\liminf_d\Delta_d\ge\underline\delta>0\). If \(\mathsf a(\overline h)>\mathsf b(\underline\delta)\), then under Assumption~\ref{ass:asymptotic-regime},
\begin{equation}
\frac{\sup_{W\in\mathcal R_d^{\mathrm{clf}}}\mathcal E_{\pi,d}(W)}{\inf_{W\in\mathcal C_d^{\mathrm{clf}}}\mathcal E_{\pi,d}(W)}\longrightarrow0,
\label{eq:app-acc-transfer-ratio}
\end{equation}
and therefore, for every sufficiently large \(d\),
\begin{equation}
\inf_{W\in\mathcal R_d^{\mathrm{clf}}}\operatorname{Acc}_{\pi,d}(W)>\sup_{W\in\mathcal C_d^{\mathrm{clf}}}\operatorname{Acc}_{\pi,d}(W).
\label{eq:app-acc-transfer-order}
\end{equation}

\label{lem:app-acc-trajectory-continuity}
Fix \(d\), a linearly separable training set \(X\) containing at least one sample from every class in \([k]\), a matrix norm \(\psi\), and \(0\le\varepsilon<\gamma_\psi(X)\). If \(d_{\cos}(W_t,\mathcal U_{\psi,\varepsilon}^X)\to0\), then
\begin{equation}
\limsup_{t\to\infty}\mathcal E_{\pi,d}(W_t)\le\sup_{U\in\mathcal U_{\psi,\varepsilon}^X}\mathcal E_{\pi,d}(U),\qquad \liminf_{t\to\infty}\mathcal E_{\pi,d}(W_t)\ge\inf_{U\in\mathcal U_{\psi,\varepsilon}^X}\mathcal E_{\pi,d}(U).
\label{eq:app-acc-error-continuity}
\end{equation}

\label{lem:app-det-metric-transfer}
Under the fixed-data assumptions of Lemma~\ref{lem:app-acc-trajectory-continuity}, if \(d_{\cos}(W_t,\mathcal U_{\psi,\varepsilon}^X)\to0\) with \(0\le\varepsilon<\gamma_\psi(X)\), then
\begin{equation}
\limsup_{t\to\infty}D_{\mathrm{avg\text{-}bdry}}(W_t)\le\sup_{U\in\mathcal U_{\psi,\varepsilon}^X}D_{\mathrm{avg\text{-}bdry}}(U),\qquad \liminf_{t\to\infty}D_{\mathrm{avg\text{-}bdry}}(W_t)\ge\inf_{U\in\mathcal U_{\psi,\varepsilon}^X}D_{\mathrm{avg\text{-}bdry}}(U).
\label{eq:app-det-metric-transfer}
\end{equation}

Work on the event \(\mathcal G_d^{\mathrm{det}}\) from Theorem~\ref{thm:deterministic-separation-clean}. Proposition~\ref{prop:app-det-common-event}, items~\ref{item:app-det-H1}--\ref{item:app-det-H2} imply \(\tau_d+\rho_d=o(1)\) on this event. Take \(\mathcal R_d^{\mathrm{clf}}=\mathcal U_{\mathrm{row}}^X\). Equation~\eqref{eq:det-row-uniform-clean} gives \(h_d=o(1)\). For \(\psi\in\{\mathrm{sp},\max\}\), take \(\mathcal C_d^{\mathrm{clf}}=\mathcal U_\psi^X\). Equations~\eqref{eq:det-sp-clean} and~\eqref{eq:det-max-clean} give \(\liminf_d\Delta_d\ge\delta_\psi>0\), where \(\delta_{\mathrm{sp}}=\delta_{\mathrm{sp}}(\alpha)\) and \(\delta_{\max}\) is defined in \eqref{eq:delta-max-clean}. Since
\begin{equation}
\mathsf a(0)=\frac1{\sqrt2}>\frac1{\sqrt2}\left(1-\frac{\delta_\psi^2}{2}\right)_+=\mathsf b(\delta_\psi),
\label{eq:app-acc-deterministic-amplitude-gap}
\end{equation}
Theorem~\ref{thm:app-acc-transfer} gives, for every sufficiently large \(d\) on \(\mathcal G_d^{\mathrm{det}}\),
\begin{equation}
\sup_{U\in\mathcal U_{\mathrm{row}}^X}\mathcal E_{\pi,d}(U)<\min_{\psi\in\{\mathrm{sp},\max\}}\inf_{V\in\mathcal U_\psi^X}\mathcal E_{\pi,d}(V).
\label{eq:app-acc-deterministic-set-error-order}
\end{equation}
The full-batch implicit-bias results in Appendix~\ref{app:max-sum-row}, together with Lemma~\ref{lem:exact-margin-direction-convergence}, give direction-set convergence to \(\mathcal U_{\mathrm{row}}^X\) for RowGD and RowGDM, to \(\mathcal U_{\mathrm{sp}}^X\) for Spectral-GD and exact-SVD Muon, and to \(\mathcal U_{\max}^X\) for SignGD, Signum, and full-batch Adam under the stated Adam assumptions. Lemma~\ref{lem:app-acc-trajectory-continuity} transfers \eqref{eq:app-acc-deterministic-set-error-order} to all seven trajectories. Since \(\mathbb P(\mathcal G_d^{\mathrm{det}})\ge1-e^{-\sqrt d}\), replacing error by one minus accuracy proves \eqref{eq:det-optimizer-accuracy-order-clean} with the claimed probability.

\label{lem:app-population-polar-transfer}
Under Assumptions~\ref{ass:gaussian-cloud} and~\ref{ass:asymptotic-regime},
\begin{equation}
\frac1{r_d}\|Q_m-Q_\mu\|_{\mathrm F}^2\xrightarrow{\mathbb P}0.
\label{eq:app-population-polar-transfer}
\end{equation}

By~\eqref{eq:app-det-mean-residual}, the \(i\)-th row of \(M_m-M_\mu\) is \(r\bar z_i^\top\), and the rows are independent centered Gaussian vectors with covariance \(r^2I_d/(n_i d)\). Hence \(M_m-M_\mu=D_d^{\mathrm e}H/\sqrt d\) for a standard Gaussian matrix \(H\) and a diagonal matrix satisfying \(\|D_d^{\mathrm e}\|_{\mathrm{op}}\le r_0/\sqrt{n_{\min}}\). Since \(k/d\to\alpha\) and \(n_{\min}\to\infty\),
\begin{equation}
\delta_d:=\|C_m-C_\mu\|_{\mathrm{op}}\le\|M_m-M_\mu\|_{\mathrm{op}}=o_{\mathbb P}(1).
\label{eq:app-population-polar-op-transfer}
\end{equation}

On the full reduced-rank event, \(\|Q_\mu\|_{\mathrm{op}}=1\), \(\operatorname{rank}(Q_\mu)=r_d\), and \(\langle Q_\mu,C_\mu\rangle=\|C_\mu\|_*\). Therefore
\begin{align}
0
&\le \|C_m\|_*-\langle Q_\mu,C_m\rangle \notag\\
&\le \bigl|\|C_m\|_*-\|C_\mu\|_*\bigr|+\bigl|\langle Q_\mu,C_m-C_\mu\rangle\bigr|
\le 2r_d\delta_d.
\label{eq:app-population-polar-deficit}
\end{align}
Write \(C_m=U_m\Sigma_mV_m^\top\), and set \(a_\ell:=1-u_{m,\ell}^\top Q_\mu v_{m,\ell}\). Then~\eqref{eq:app-population-polar-deficit} gives
\begin{equation}
\frac1{r_d}\sum_{\ell=1}^{r_d}\sigma_\ell(C_m)a_\ell\le2\delta_d.
\label{eq:app-population-polar-weighted-deficit}
\end{equation}

If \(\alpha\neq1\), Proposition~\ref{prop:app-det-spectral-input}, item~\ref{item:app-det-S5}, bounds every positive singular value of \(C_m\) away from zero, so Lemma~\ref{lem:app-det-trace-truncation} and~\eqref{eq:app-population-polar-weighted-deficit} yield \(r_d^{-1}\|Q_m-Q_\mu\|_{\mathrm F}^2=o_{\mathbb P}(1)\).

Suppose \(\alpha=1\). Choose a deterministic sequence \(\bar\delta_d\downarrow0\) such that \(\delta_d\le\bar\delta_d\) with probability tending to one, and set \(\tau_d:=\max\{\eta_d,\sqrt{\bar\delta_d}\}\), where \(\eta_d\) is the envelope in Proposition~\ref{prop:app-det-spectral-input}. For all sufficiently large \(d\), \(\tau_d\le t_0\), and item~\ref{item:app-det-S5} together with Lemma~\ref{lem:app-det-trace-truncation} gives
\[
\frac1{r_d}\|Q_m-Q_\mu\|_{\mathrm F}^2
\le 4C_0(\tau_d+\eta_d)+\frac{4\delta_d}{\tau_d}
=o_{\mathbb P}(1).
\]
This proves~\eqref{eq:app-population-polar-transfer}.

We first establish the claimed geometry uniformly over the corresponding exact maximum-margin faces.

For the Row geometry, Proposition~\ref{prop:app-det-row-rigidity} and Proposition~\ref{prop:app-det-common-event}, item~\ref{item:app-det-H1}, give
\begin{equation}
\sup_{W\in\mathcal M_{\mathrm{row}}^X}\max_i\|w_i-\mu_i\|_2=o_{\mathbb P}(1).
\label{eq:app-limiting-row-population-rigidity}
\end{equation}
Since \(\min_i\|\mu_i\|_2=1-o_{\mathbb P}(1)\), Lemma~\ref{lem:app-det-normalization} yields
\begin{equation}
\sup_{W\in\mathcal M_{\mathrm{row}}^X}\max_i\|\widehat w_i-\widehat\mu_i\|_2=o_{\mathbb P}(1).
\label{eq:app-limiting-row-direction}
\end{equation}

For the Max geometry, put \(g:=\sqrt{2/\pi}\), let \(T_i:=\operatorname{sign}(\mu_i)\), and write \(t_{\max}:=r_{\max}^*(X)\). For \(W\in\mathcal M_{\max}^X\), set \(A:=W/t_{\max}\). The sharp radius estimate~\eqref{eq:app-det-sharp-radii} and the global sign rigidity~\eqref{eq:app-det-sharp-global-sign} imply
\begin{equation}
t_{\max}=\frac{1+o_{\mathbb P}(1)}{g\sqrt d},\qquad
\sup_{W\in\mathcal M_{\max}^X}\frac{\|A-T\|_{\mathrm F}^2}{kd}=o_{\mathbb P}(1),
\label{eq:app-limiting-max-global}
\end{equation}
where \(T\) has rows \(T_i^\top\). Let \(\bar A:=k^{-1}\sum_iA_i\) and \(\bar T:=k^{-1}\sum_iT_i\). Jensen's inequality,~\eqref{eq:app-limiting-max-global}, and \(\mathbb E\|\bar T\|_2^2=d/k=O(1)\) give \(\sup_W\|\bar A\|_2/\sqrt d=o_{\mathbb P}(1)\). The class-averaged feasibility constraint~\eqref{eq:app-det-row-centering-constraint} then gives, uniformly over \(i\) and \(W\in\mathcal M_{\max}^X\),
\[
A_i^\top\mu_i\ge g\sqrt d-o_{\mathbb P}(\sqrt d).
\]
Together with \(\max_i|\|\mu_i\|_1/\sqrt d-g|=o_{\mathbb P}(1)\) from~\eqref{eq:app-det-sharp-gaussian-inputs}, this implies \(D_i:=\|\mu_i\|_1-A_i^\top\mu_i=o_{\mathbb P}(\sqrt d)\) uniformly. Substituting this bound into~\eqref{eq:app-det-sharp-row-split} and using the uniform Gaussian small-ball estimate~\eqref{eq:app-det-sharp-small-ball} yields
\begin{equation}
\sup_{W\in\mathcal M_{\max}^X}\max_i\frac1d\|A_i-T_i\|_2^2=o_{\mathbb P}(1).
\label{eq:app-limiting-max-row-rigidity}
\end{equation}
Since \(\|T_i\|_2=\sqrt d\), normalization stability gives
\begin{equation}
\sup_{W\in\mathcal M_{\max}^X}\max_i\left\|\widehat w_i-\frac{\operatorname{sign}(\mu_i)}{\sqrt d}\right\|_2=o_{\mathbb P}(1).
\label{eq:app-limiting-max-direction}
\end{equation}

For the Spectral geometry, let \(B:=PW/\|PW\|_{\mathrm{op}}\). Combining~\eqref{eq:app-det-spectral-frobenius-rigidity} with Lemma~\ref{lem:app-population-polar-transfer} gives
\begin{equation}
\sup_{W\in\mathcal M_{\mathrm{sp}}^X}\frac1{r_d}\|B-Q_\mu\|_{\mathrm F}^2=o_{\mathbb P}(1).
\label{eq:app-limiting-spectral-population-rigidity}
\end{equation}
This proves the population-mean version of the spectral geometry claimed in the proposition.

It remains to identify the mean angles when \(\alpha>1\). For Row,~\eqref{eq:app-limiting-row-direction} immediately gives a limiting angle of zero. For Max,~\eqref{eq:app-limiting-max-direction}, \(\max_i|\|\mu_i\|_2-1|=o_{\mathbb P}(1)\), and~\eqref{eq:app-det-sharp-gaussian-inputs} give
\begin{equation}
\sup_{W\in\mathcal M_{\max}^X}\max_i\left|
\frac{w_i^\top\mu_i}{\|w_i\|_2\|\mu_i\|_2}
-\sqrt{\frac2\pi}
\right|=o_{\mathbb P}(1).
\label{eq:app-limiting-max-angle-cosine}
\end{equation}

For Spectral, \(\alpha>1\) implies \(r_d=d\). Since \(C_\mu\) is a centered Gaussian matrix, the left singular frame \(U_\mu\) is Haar in \(\mathbf1^\perp\) and independent of its singular values. Haar-projector concentration and the Marchenko--Pastur limit therefore give
\begin{equation}
\max_i\left|\|q_i\|_2^2-\frac1\alpha\right|=o_{\mathbb P}(1),\qquad
\max_i\left|q_i^\top\mu_i-s_\alpha\right|=o_{\mathbb P}(1).
\label{eq:app-limiting-population-polar-row}
\end{equation}
Indeed, if \(S_\mu:=Q_\mu C_\mu^\top=U_\mu\Sigma_\mu U_\mu^\top\), conditional Haar concentration gives \(\max_i|S_\mu[i,i]-\|C_\mu\|_*/k|=o_{\mathbb P}(1)\), while \(\|C_\mu\|_*/k\to s_\alpha\) and \(q_i^\top(\mu_i-\bar\mu)=S_\mu[i,i]\) with \(\|\bar\mu\|_2=o_{\mathbb P}(1)\). Since \(s_\alpha=m_{1/2}(\alpha)/\sqrt\alpha\) and \(\kappa_{\mathrm{sp}}(\alpha)=m_{1/2}(\alpha)\) for \(\alpha>1\),~\eqref{eq:app-limiting-population-polar-row} yields
\begin{equation}
\max_i\left|
\frac{q_i^\top\mu_i}{\|q_i\|_2\|\mu_i\|_2}
-\kappa_{\mathrm{sp}}(\alpha)
\right|=o_{\mathbb P}(1).
\label{eq:app-limiting-population-polar-cosine}
\end{equation}

We now transfer~\eqref{eq:app-limiting-population-polar-cosine} from \(Q_\mu\) to arbitrary exact Spectral minimizers. Fix \(W\in\mathcal M_{\mathrm{sp}}^X\), set \(a:=\|W\|_{\mathrm{op}}\), and let \(\bar w:=k^{-1}\sum_iw_i\) and \(h:=\bar w/a\). Centering preserves every margin and cannot increase the operator norm, so exact optimality gives \(\|PW\|_{\mathrm{op}}=\|W\|_{\mathrm{op}}=a\). Hence, with \(B:=PW/a\),
\begin{equation}
\frac Wa=B+\mathbf1h^\top,\qquad \mathbf1^\top B={\mathbf 0}^\top.
\label{eq:app-limiting-spectral-shift}
\end{equation}
Because \(\|Q_\mu\|_{\mathrm F}^2=d\),~\eqref{eq:app-limiting-spectral-population-rigidity} gives \(\|B\|_{\mathrm F}^2=d-o_{\mathbb P}(d)\) uniformly over \(\mathcal M_{\mathrm{sp}}^X\). The two terms in~\eqref{eq:app-limiting-spectral-shift} are Frobenius-orthogonal, while \(\|W/a\|_{\mathrm{op}}=1\) implies \(\|W/a\|_{\mathrm F}^2\le d\). Therefore
\[
d\ge\left\|\frac Wa\right\|_{\mathrm F}^2=\|B\|_{\mathrm F}^2+k\|h\|_2^2,
\]
and hence
\begin{equation}
\sup_{W\in\mathcal M_{\mathrm{sp}}^X}\|h\|_2=o_{\mathbb P}(1).
\label{eq:app-limiting-spectral-shift-small}
\end{equation}
Consequently,
\begin{equation}
\sup_{W\in\mathcal M_{\mathrm{sp}}^X}\frac1k\sum_{i=1}^k\left\|\frac{w_i}{a}-q_i\right\|_2^2
=
\sup_{W\in\mathcal M_{\mathrm{sp}}^X}\left\{\frac1k\|B-Q_\mu\|_{\mathrm F}^2+\|h\|_2^2\right\}
=o_{\mathbb P}(1).
\label{eq:app-limiting-spectral-row-average}
\end{equation}
Moreover, every spectral row is nonzero with probability tending to one: if \(w_i={\mathbf 0}\), then~\eqref{eq:app-det-row-centering-constraint} gives \(-ah^\top m_i\ge1-1/k\), contradicting \(a=O_{\mathbb P}(1)\),~\eqref{eq:app-limiting-spectral-shift-small}, and \(\max_i\|m_i\|_2=O_{\mathbb P}(1)\). Since~\eqref{eq:app-limiting-population-polar-row} bounds \(\min_i\|q_i\|_2\) away from zero,~\eqref{eq:app-limiting-spectral-row-average} and normalization stability imply that, for every fixed \(\varepsilon>0\),
\begin{equation}
\sup_{W\in\mathcal M_{\mathrm{sp}}^X}\frac1k\#\left\{i:
\left|
\arccos\!\left(\frac{w_i^\top\mu_i}{\|w_i\|_2\|\mu_i\|_2}\right)
-\arccos\kappa_{\mathrm{sp}}(\alpha)
\right|>\varepsilon
\right\}
\xrightarrow{\mathbb P}0.
\label{eq:app-limiting-spectral-angle-fraction}
\end{equation}
Because every angle lies in \([0,\pi]\),~\eqref{eq:app-limiting-spectral-angle-fraction} implies
\begin{equation}
\sup_{W\in\mathcal M_{\mathrm{sp}}^X}\left|
\frac1k\sum_{i=1}^k
\arccos\!\left(\frac{w_i^\top\mu_i}{\|w_i\|_2\|\mu_i\|_2}\right)
-\arccos\kappa_{\mathrm{sp}}(\alpha)
\right|
\xrightarrow{\mathbb P}0.
\label{eq:app-limiting-spectral-mean-angle}
\end{equation}

Finally,~\eqref{eq:minmax-equivalence-clean} identifies each maximum-margin direction set with the positive rays through the corresponding exact minimum-norm face. The full-batch implicit-bias results used in Theorem~\ref{thm:det-optimizer-accuracy-order-clean}, together with Lemma~\ref{lem:exact-margin-direction-convergence}, give direction-set convergence to \(\mathcal U_{\mathrm{row}}^X\) for RowGD and RowGDM, to \(\mathcal U_{\mathrm{sp}}^X\) for SpecGD and Muon, and to \(\mathcal U_{\max}^X\) for SignGD, Signum, and Adam. At each fixed \(d\), the normalized row directions, the centered spectral representative \(PW/\|PW\|_{\mathrm{op}}\), and the mean class--row angle are continuous on the corresponding compact direction sets on the high-probability events established above. Taking \(t\to\infty\) first and then \(d\to\infty\) therefore transfers~\eqref{eq:app-limiting-row-direction},~\eqref{eq:app-limiting-max-direction},~\eqref{eq:app-limiting-spectral-population-rigidity}, and the three angle limits to the optimizer trajectories, proving Proposition~\ref{prop:limiting-geometry}.

\label{lem:app-det-exponent-reduction}
For every classifier with nonzero pairwise row differences, set \(I_d(W):=d\mathsf E_d(W)/(2r_{\mathrm{te}}^2)\) and \(C_0:=3/2+\frac12\log(2\pi)\). Then
\begin{equation}
\max\{0,I_d(W)-\log(k-1)\}\le-\log\mathcal E_{\pi,d}(W)\le I_d(W)+\log(1/\pi_{\min,d})+\log(1+\sqrt{2I_d(W)})+C_0.
\label{eq:app-det-exponent-reduction}
\end{equation}
Consequently, uniformly over any classifier family on which \(\mathsf E_d(W)=O(1)\), one has \(\mathsf F_d(W)=\mathsf E_d(W)+o(1)\) under Assumption~\ref{ass:asymptotic-regime}.

\label{prop:app-det-sharp-directed-signals}
Under Assumptions~\ref{ass:gaussian-cloud} and~\ref{ass:asymptotic-regime}, in probability,
\begin{equation}
r_{\max}^*(X)=\frac{1+o(1)}{g\sqrt d},\qquad r_{\mathrm{sp}}^*(X)=\frac{1+o(1)}{s_\alpha}.
\label{eq:app-det-sharp-radii}
\end{equation}
Moreover, uniformly over the complete exact faces,
\begin{align}
\sup_{W\in\mathcal M_{\max}^X}\max_{i\ne j}\left|(u_{ij}^W)^\top\mu_i-\frac1{\sqrt\pi}\right|&=o_{\mathbb P}(1),
\label{eq:app-det-max-sharp-signal}\\
\inf_{W\in\mathcal M_{\mathrm{sp}}^X}\min_{i\ne j}(u_{ij}^W)^\top\mu_i&\ge\frac{s_\alpha}{\sqrt2}-o_{\mathbb P}(1).
\label{eq:app-det-spectral-sharp-signal}
\end{align}

Let \(M_\mu\) have rows \(\mu_i^\top\), let \(C_\mu:=PM_\mu\), and let \(T:=\operatorname{sign}(M_\mu)\). Standard Gaussian concentration, uniformly over the \(k=\Theta(d)\) classes, gives
\begin{equation}
\frac{\|C_\mu\|_{\mathrm{sum}}}{k\sqrt d}=g+o_{\mathbb P}(1),\qquad \max_i\left|\frac{\|\mu_i\|_1}{\sqrt d}-g\right|=o_{\mathbb P}(1),\qquad \max_{i\ne j}\frac{|T_j^\top\mu_i|}{\sqrt d}=o_{\mathbb P}(1),
\label{eq:app-det-sharp-gaussian-inputs}
\end{equation}
and, for every fixed \(a>0\),
\begin{equation}
\frac1{kd}\#\{(i,\ell):\sqrt d\,|C_\mu[i,\ell]|\le a\}\xrightarrow{\mathbb P}\mathbb P(|G|\le a),\qquad \max_i\frac1d\#\{\ell:\sqrt d\,|\mu_i[\ell]|\le a\}\le\mathbb P(|G|\le a)+o_{\mathbb P}(1).
\label{eq:app-det-sharp-small-ball}
\end{equation}
Also \(\|C_m-C_\mu\|_{\mathrm{sum}}=o_{\mathbb P}(k\sqrt d)\) by Proposition~\ref{prop:app-det-common-event}. Every feasible \(W\) satisfies the averaged exposure inequality \(\langle W,C_m\rangle\ge k-1\). Max--sum duality and \eqref{eq:app-det-sharp-gaussian-inputs} therefore give \(r_{\max}^*(X)\ge(1+o_{\mathbb P}(1))/(g\sqrt d)\), while Proposition~\ref{prop:app-det-common-event}, item~\ref{item:app-det-H5} gives the matching upper bound. Similarly, operator--nuclear duality and Proposition~\ref{prop:app-det-spectral-input}, item~\ref{item:app-det-S1} give \(r_{\mathrm{sp}}^*(X)\ge(1+o_{\mathbb P}(1))/s_\alpha\), while the polar witness \(Q_m/\rho_X\) and Proposition~\ref{prop:app-det-spectral-input}, item~\ref{item:app-det-S3} give the matching upper bound. This proves \eqref{eq:app-det-sharp-radii}.

Fix \(W\in\mathcal M_{\max}^X\) and set \(A:=W/r_{\max}^*(X)\), so \(\|A\|_{\max}=1\). The exposure inequality and the exact Max radius imply
\begin{equation}
\langle A,C_\mu\rangle\ge\|C_\mu\|_{\mathrm{sum}}-o_{\mathbb P}(k\sqrt d)
\label{eq:app-det-sharp-max-exposure}
\end{equation}
uniformly over the complete Max face. Put \(S:=\operatorname{sign}(C_\mu)\) and \(\Delta_{i\ell}:=1-A[i,\ell]S[i,\ell]\in[0,2]\). Since \((A[i,\ell]-S[i,\ell])^2=\Delta_{i\ell}^2\le2\Delta_{i\ell}\), for every fixed \(a>0\),
\begin{equation}
\frac{\|A-S\|_{\mathrm F}^2}{kd}\le\frac{2\sqrt d}{akd}\left(\|C_\mu\|_{\mathrm{sum}}-\langle A,C_\mu\rangle\right)+\frac4{kd}\#\{(i,\ell):\sqrt d\,|C_\mu[i,\ell]|\le a\}.
\label{eq:app-det-sharp-global-split}
\end{equation}
First sending \(d\to\infty\) and then \(a\downarrow0\) gives \(\sup_W\|A-S\|_{\mathrm F}^2/(kd)=o_{\mathbb P}(1)\). Since \(C_\mu[i,\ell]=\mu_i[\ell]-\bar\mu[\ell]\), where \(\bar\mu=k^{-1}\sum_i\mu_i\) and \(\|\bar\mu\|_2=o_{\mathbb P}(1)\), the same small-ball argument transfers \(S\) to \(T\), yielding
\begin{equation}
\sup_{W\in\mathcal M_{\max}^X}\frac{\|A-T\|_{\mathrm F}^2}{kd}=o_{\mathbb P}(1).
\label{eq:app-det-sharp-global-sign}
\end{equation}
Let \(\bar A=k^{-1}\sum_iA_i\) and \(\bar T=k^{-1}\sum_iT_i\). Jensen's inequality and \eqref{eq:app-det-sharp-global-sign}, together with \(\mathbb E\|\bar T\|_2^2=d/k=O(1)\), imply \(\sup_W\|\bar A\|_2/\sqrt d=o_{\mathbb P}(1)\). Averaging the class-\(i\) constraints over its samples and over all competitors gives
\[
(A_i-\bar A)^\top m_i\ge\frac{k-1}{k\,r_{\max}^*(X)}=g\sqrt d-o_{\mathbb P}(\sqrt d).
\]
Proposition~\ref{prop:app-det-common-event}, item~\ref{item:app-det-H1}, the bound \(\|A_i-\bar A\|_2\le2\sqrt d\), and the preceding control of \(\bar A\) therefore imply \(A_i^\top\mu_i\ge g\sqrt d-o_{\mathbb P}(\sqrt d)\) uniformly over \(i\) and the complete face. The nonnegative deficiency \(D_i:=\|\mu_i\|_1-A_i^\top\mu_i\) is thus \(o_{\mathbb P}(\sqrt d)\) uniformly. For every fixed \(a>0\),
\begin{equation}
\frac1d\|A_i-T_i\|_2^2\le\frac{2D_i}{a\sqrt d}+\frac4d\#\{\ell:\sqrt d\,|\mu_i[\ell]|\le a\}.
\label{eq:app-det-sharp-row-split}
\end{equation}
Using \eqref{eq:app-det-sharp-small-ball} and then sending \(a\downarrow0\) proves \(\sup_W\max_i\|A_i-T_i\|_2/\sqrt d=o_{\mathbb P}(1)\). Finally, uniformly over \(i\ne j\), \((T_i-T_j)^\top\mu_i=g\sqrt d+o_{\mathbb P}(\sqrt d)\) and \(\|T_i-T_j\|_2=\sqrt{2d}+o_{\mathbb P}(\sqrt d)\), which proves \eqref{eq:app-det-max-sharp-signal}.

For Spectral, class-average feasibility gives \((w_i-w_j)^\top m_i\ge1\), while \(\|w_i-w_j\|_2\le\sqrt2\|W\|_{\mathrm{op}}=\sqrt2\,r_{\mathrm{sp}}^*(X)\). Proposition~\ref{prop:app-det-common-event}, item~\ref{item:app-det-H1} and \eqref{eq:app-det-sharp-radii} therefore give \((u_{ij}^W)^\top\mu_i\ge s_\alpha/\sqrt2-o_{\mathbb P}(1)\) uniformly, proving \eqref{eq:app-det-spectral-sharp-signal}.

\label{prop:app-det-error-exponents}
Under Assumptions~\ref{ass:gaussian-cloud} and~\ref{ass:asymptotic-regime}, uniformly over the indicated complete maximum-margin direction sets,
\begin{align}
\sup_{R\in\mathcal U_{\mathrm{row}}^X}\left|\mathsf F_d(R)-\frac12\right|&=o_{\mathbb P}(1),
\label{eq:app-det-row-exponent}\\
\sup_{M\in\mathcal U_{\max}^X}\left|\mathsf F_d(M)-\frac1\pi\right|&=o_{\mathbb P}(1),
\label{eq:app-det-max-exponent}\\
\frac{s_\alpha^2}{2}-o_{\mathbb P}(1)\le\mathsf F_d(S)&\le\frac{\kappa_{\mathrm{sp}}(\alpha)^2}{2}+o_{\mathbb P}(1),\qquad S\in\mathcal U_{\mathrm{sp}}^X.
\label{eq:app-det-spectral-exponent}
\end{align}
Consequently, for \(0<\alpha\le1\), the spectral interval collapses to \(\kappa_{\mathrm{sp}}(\alpha)^2/2\); at \(\alpha=1\), this value is \(32/(9\pi^2)\). Uniformly over \(R\in\mathcal U_{\mathrm{row}}^X\), \(M\in\mathcal U_{\max}^X\), and \(S\in\mathcal U_{\mathrm{sp}}^X\),
\begin{equation}
\log\frac{\mathcal E_{\pi,d}(M)}{\mathcal E_{\pi,d}(R)}=\left(\frac{\pi-2}{4\pi}+o_{\mathbb P}(1)\right)\frac d{r_{\mathrm{te}}^2},
\label{eq:app-det-row-max-error-gain}
\end{equation}
\begin{equation}
\frac{1-\kappa_{\mathrm{sp}}(\alpha)^2}{2}-o_{\mathbb P}(1)\le\frac{2r_{\mathrm{te}}^2}{d}\log\frac{\mathcal E_{\pi,d}(S)}{\mathcal E_{\pi,d}(R)}\le\frac{1-s_\alpha^2}{2}+o_{\mathbb P}(1).
\label{eq:app-det-row-spectral-error-gain}
\end{equation}
The Row--Spectral gain is exact when \(\alpha\le1\).

\label{cor:app-det-optimizer-error-exponents}
Under the assumptions and optimizer conventions of Theorem~\ref{thm:det-optimizer-accuracy-order-clean}, the deterministic full-batch optimizer trajectories satisfy, in probability,
\begin{align}
\limsup_{t\to\infty}\left|\mathsf F_d\!\left(W_t^{\mathrm{RowGDM}}\right)-\frac12\right|&=o_{\mathbb P}(1),
\label{eq:app-rowgdm-error-exponent}\\
\limsup_{t\to\infty}\left|\mathsf F_d\!\left(W_t^{\mathrm{Adam}}\right)-\frac1\pi\right|&=o_{\mathbb P}(1).
\label{eq:app-adam-error-exponent}
\end{align}
Exact-SVD Muon satisfies
\begin{equation}
\frac{s_\alpha^2}{2}-o_{\mathbb P}(1)\le\liminf_{t\to\infty}\mathsf F_d\!\left(W_t^{\mathrm{Muon}}\right)\le\limsup_{t\to\infty}\mathsf F_d\!\left(W_t^{\mathrm{Muon}}\right)\le\frac{\kappa_{\mathrm{sp}}(\alpha)^2}{2}+o_{\mathbb P}(1).
\label{eq:app-muon-error-exponent}
\end{equation}
Define the Row--Spectral exponent-gap constant
\begin{equation}
\Delta_{\rm exp}(\alpha):=\frac{1-\kappa_{\mathrm{sp}}(\alpha)^2}{4}=\frac14\left(1-\frac{m_{1/2}(\alpha)^2}{\alpha\wedge1}\right)>0,
\qquad
m_{1/2}(\alpha):=\frac{\alpha}{2\pi}\int_{a_\alpha}^{b_\alpha}\frac{\sqrt{(b_\alpha-x)(x-a_\alpha)}}{\sqrt{x}}\,dx,
\label{eq:app-det-c-alpha}
\end{equation}
where
\begin{equation}
a_\alpha=(1-\alpha^{-1/2})^2,\qquad b_\alpha=(1+\alpha^{-1/2})^2.
\end{equation}
Equivalently,
\begin{equation}
\Delta_{\rm exp}(\alpha)=\frac14\left[1-\frac{\alpha^2}{4\pi^2(\alpha\wedge1)}\left(\int_{a_\alpha}^{b_\alpha}\frac{\sqrt{(b_\alpha-x)(x-a_\alpha)}}{\sqrt{x}}\,dx\right)^2\right].
\label{eq:app-det-c-alpha-expanded}
\end{equation}
For example,
\begin{equation}
\Delta_{\rm exp}(1)=\frac14\left(1-\frac{64}{9\pi^2}\right)\approx0.06987,\qquad \Delta_{\rm exp}(2)\approx0.03247,\qquad \Delta_{\rm exp}(3)\approx0.02133.
\label{eq:app-det-c-alpha-examples}
\end{equation}
Consequently,
\begin{equation}
\limsup_{t\to\infty}\left|\frac{r_{\mathrm{te}}^2}{d}\log\frac{\mathcal E_{\pi,d}(W_t^{\mathrm{Adam}})}{\mathcal E_{\pi,d}(W_t^{\mathrm{RowGDM}})}-\frac{\pi-2}{4\pi}\right|=o_{\mathbb P}(1),
\label{eq:app-rowgdm-adam-error-gain}
\end{equation}
and
\begin{align}
\Delta_{\rm exp}(\alpha)-o_{\mathbb P}(1)
&\le\liminf_{t\to\infty}\frac{r_{\mathrm{te}}^2}{d}\log\frac{\mathcal E_{\pi,d}(W_t^{\mathrm{Muon}})}{\mathcal E_{\pi,d}(W_t^{\mathrm{RowGDM}})}
\nonumber\\
&\le\limsup_{t\to\infty}\frac{r_{\mathrm{te}}^2}{d}\log\frac{\mathcal E_{\pi,d}(W_t^{\mathrm{Muon}})}{\mathcal E_{\pi,d}(W_t^{\mathrm{RowGDM}})}
\le\frac{1-s_\alpha^2}{4}+o_{\mathbb P}(1).
\label{eq:app-rowgdm-muon-error-gain}
\end{align}
The same conclusions hold with RowGDM replaced by RowGD, with Adam replaced by SignGD or Signum, and with Muon replaced by Spectral-GD. When \(0<\alpha\le1\), the two Row--Muon bounds coincide. Here, \(o_{\mathbb P}(1)\) refers to the limit \(d\to\infty\), after taking \(t\to\infty\) at each fixed \(d\).

\label{cor:app-det-muon-adam-order}
Under the assumptions and optimizer conventions of Theorem~\ref{thm:det-optimizer-accuracy-order-clean}, suppose \(0<\alpha<\alpha_\star\), where \(\alpha_\star\approx1.225\) is the aspect-ratio threshold defined by \(s_{\alpha_\star}^2=2/\pi\). Then, with
\[
c_{\mathrm{MA}}(\alpha):=\frac14\left(s_\alpha^2-\frac2\pi\right)>0,
\]
the deterministic full-batch trajectories satisfy
\begin{equation}
\limsup_{t\to\infty}\frac{r_{\mathrm{te}}^2}{d}\log\frac{\mathcal E_{\pi,d}(W_t^{\mathrm{Muon}})}{\mathcal E_{\pi,d}(W_t^{\mathrm{Adam}})}\le -c_{\mathrm{MA}}(\alpha)+o_{\mathbb P}(1).
\label{eq:app-det-muon-adam-order}
\end{equation}
Thus exact-SVD Muon has asymptotically smaller population error, and hence higher population accuracy, than full-batch Adam with probability tending to one. The same conclusion holds with Muon replaced by Spectral-GD and Adam replaced by SignGD or Signum.

\label{lem:app-stoch-near-reduction}
Fix a linearly separable dataset \(X\), a matrix norm \(\psi\), and \(0\le\varepsilon<\gamma_\psi(X)\). For every \(U\in\mathcal U_{\psi,\varepsilon}^X\), define
\begin{equation}
V_U:=\frac{U}{\operatorname{mar}_X(U)},\qquad \xi_\psi(\varepsilon;X):=\frac{\varepsilon}{\gamma_\psi(X)-\varepsilon}.
\label{eq:app-stoch-near-representative}
\end{equation}
Then \(V_U\in\mathcal F_X\),
\begin{equation}
\psi(V_U)\le\left(1+\xi_\psi(\varepsilon;X)\right)r_\psi^*(X),
\label{eq:app-stoch-near-norm-bound}
\end{equation}
and \(V_U\) has the same normalized pairwise row differences as \(U\).

\label{lem:app-stoch-combined-input}
There are deterministic \(\omega_d\downarrow0\), constants \(C,c>0\), and events \(\mathcal E_d^{\mathrm{near}}\) such that
\begin{equation}
\mathbb P\!\left((\mathcal E_d^{\mathrm{near}})^c\right)\le C\exp\!\left[-c\sqrt{d\log(2N(d)(d+1))}\right],
\label{eq:app-stoch-near-event-probability}
\end{equation}
all conclusions of Propositions~\ref{prop:app-det-common-event} and~\ref{prop:app-det-spectral-input} hold with their vanishing errors bounded by \(\omega_d\), and
\begin{equation}
\max_{i,s}\|x_{i,s}\|_2\le1+2r_0+\omega_d,\qquad \max_{i,s}\|x_{i,s}\|_1\le(1+2r_0+\omega_d)\sqrt d.
\label{eq:app-stoch-data-radius-bounds}
\end{equation}
We may additionally take \(\omega_d\ge1/k\).

\label{prop:app-stoch-near-stability}
There are constants \(C_{\mathrm{row}},C_{\max}>0\) and \(C_{\mathrm{sp}}(\alpha)>0\) such that, on \(\mathcal E_d^{\mathrm{near}}\), for every \(0\le\xi\le1\),
\begin{align}
W\in\mathcal F_X,\ \|W\|_{\mathrm{row}}\le(1+\xi)r_{\mathrm{row}}^*(X)&\Longrightarrow \max_{i\ne j}\|u_{ij}^W-u_{ij}^{\mu}\|_2\le C_{\mathrm{row}}(\omega_d+\xi)^{1/4},
\label{eq:app-stoch-row-near-stability}\\
W\in\mathcal F_X,\ \|W\|_{\mathrm{op}}\le(1+\xi)r_{\mathrm{sp}}^*(X)\Longrightarrow& D_{\mathrm{avg\text{-}bdry}}(W)\ge\delta_{\mathrm{sp}}(\alpha)-C_{\mathrm{sp}}(\alpha)(\omega_d+\xi)^{1/4},
\label{eq:app-stoch-sp-near-stability}\\
W\in\mathcal F_X,\
\|W\|_{\max}\le(1+\xi)r_{\max}^*(X)&\Longrightarrow D_{\mathrm{avg\text{-}bdry}}(W)\ge\delta_{\max}-C_{\max}(\omega_d+\xi).
\label{eq:app-stoch-max-near-stability}
\end{align}

For the row norm, put \(q:=\omega_d+\xi\). The empirical-mean witness in Proposition~\ref{prop:app-det-row-rigidity} gives \(r_{\mathrm{row}}^*(X)\le1+C\omega_d\), so \(\max_i\|w_i\|_2\le1+Cq\). Averaging feasibility within class \(i\) and then over all competing classes gives \((w_i-\bar w)^\top m_i\ge1-1/k\). The row variance identity then gives \(\|\bar w\|_2^2\le Cq\), and substituting this bound back into the averaged margin inequality yields \(\max_i\|w_i-m_i\|_2\le Cq^{1/4}\). The mean perturbation in Proposition~\ref{prop:app-det-common-event} and Lemma~\ref{lem:app-det-normalization} prove~\eqref{eq:app-stoch-row-near-stability}.

For the spectral norm, Proposition~\ref{prop:app-det-spectral-rigidity} gives an error \(C_\alpha q^{1/2}\) when \(\alpha\ne1\) and \(Cq^{1/4}\) when \(\alpha=1\). Since \(q^{1/2}\le q^{1/4}\) for \(q\le1\), enlarging the constant proves~\eqref{eq:app-stoch-sp-near-stability} uniformly over all aspect ratios.

For the max norm, fix \(i\ne j\), set \(v:=w_i-w_j\), and put \(u:=u_{ij}^m\). Near-optimality and Proposition~\ref{prop:app-det-common-event}(H5) give
\begin{equation}
\|v\|_\infty\le\frac{\sqrt{2\pi}+Cq}{\sqrt d}.
\label{eq:app-stoch-max-near-cap}
\end{equation}
The two class-averaged feasibility constraints imply \(v^\top(m_i-m_j)\ge2\), and hence \(v^\top u\ge\sqrt2-Cq\). Applying the clipped minimum-energy characterization in Proposition~\ref{prop:app-det-clipped-exact}, the uniform empirical laws in Proposition~\ref{prop:app-det-common-event}(H6), and Lemma~\ref{lem:app-det-clipped-asymptotic} gives
\begin{equation}
\frac{v^\top u}{\|v\|_2}\le\kappa_{\max}+Cq.
\label{eq:app-stoch-max-near-cosine}
\end{equation}
The cosine-distance identity and Proposition~\ref{prop:app-det-common-event}(H4) prove~\eqref{eq:app-stoch-max-near-stability}.

\label{prop:app-stoch-ratio-bounds}
On \(\mathcal E_d^{\mathrm{near}}\), for every sufficiently large \(d\),
\begin{equation}
\frac{R_{\mathrm{row}}(X)}{\gamma_{\mathrm{row}}(X)}\le K_{\mathrm{row}},\qquad \frac{R_{\mathrm{sp}}(X)}{\gamma_{\mathrm{sp}}(X)}\le K_{\mathrm{sp}},\qquad \frac{R_{\max}(X)}{\gamma_{\max}(X)}\le K_{\max},
\label{eq:app-stoch-ratio-bounds}
\end{equation}
where one may take
\begin{equation}
K_{\mathrm{row}}:=4(1+2r_0),\qquad K_{\mathrm{sp}}:=\frac{8(1+2r_0)}{s_\alpha},\qquad K_{\max}:=(\sqrt{2\pi}+1)(1+2r_0).
\label{eq:app-stoch-ratio-constants}
\end{equation}

\label{prop:app-stoch-near-geometry}
\label{thm:stochastic-separation-clean}
Under the data and batching assumptions of Proposition~\ref{thm:stoch-optimizer-accuracy-order-clean}, fix \(\beta\in[\beta_0,1)\). Then, for every sufficiently large \(d\), on \(\mathcal E_d^{\mathrm{near}}\), all three effective margins \(\gamma_\psi(X)-\varepsilon_{\psi,\beta,b}(X)\) are positive and
\begin{align}
\sup_{U\in\mathcal U_{\mathrm{row},\beta,b}^X}\max_{i\ne j}\|u_{ij}^U-u_{ij}^{\mu}\|_2&\le h_*,
\label{eq:app-stoch-row-set-upper}\\
\inf_{V\in\mathcal U_{\mathrm{sp},\beta,b}^X}D_{\mathrm{avg\text{-}bdry}}(V)&\ge\frac{\delta_*}{2},
\label{eq:app-stoch-sp-set-lower}\\
\inf_{V\in\mathcal U_{\max,\beta,b}^X}D_{\mathrm{avg\text{-}bdry}}(V)&\ge\frac{\delta_*}{2}.
\label{eq:app-stoch-max-set-lower}
\end{align}
Moreover, after increasing the deterministic dimension threshold if necessary,
\begin{equation}
\mathbb P(\mathcal E_d^{\mathrm{near}})\ge1-e^{-\sqrt d}.
\label{eq:app-stoch-clean-probability}
\end{equation}

Fix \(\beta\in[\beta_0,1)\), and let \(\mathcal R_d\) be the Gaussian radial event from Lemma~\ref{lem:app-acc-gaussian-radial-event}. Set
\[
\mathcal H_d:=\mathcal E_d^{\mathrm{near}}\cap\mathcal R_d.
\]
By~\eqref{eq:app-stoch-near-event-probability} and~\eqref{eq:app-acc-radial-event-probability}, after increasing the deterministic dimension threshold,
\begin{equation}
\mathbb P(\mathcal H_d)\ge1-e^{-\sqrt d}.
\label{eq:app-stoch-accuracy-event}
\end{equation}

Work on \(\mathcal H_d\). Define the Row family
\[
\mathcal R_d^{\mathrm{clf}}:=\mathcal U_{\mathrm{row},\beta,b}^X
\]
and, for \(\psi\in\{\mathrm{sp},\max\}\), the competitor family
\[
\mathcal C_{\psi,d}^{\mathrm{clf}}:=\mathcal U_{\psi,\beta,b}^X.
\]
Proposition~\ref{prop:app-stoch-near-geometry} gives
\begin{equation}
\sup_{U\in\mathcal R_d^{\mathrm{clf}}}\max_{i\ne j}\|u_{ij}^U-u_{ij}^{\mu}\|_2\le h_*,
\qquad
\inf_{V\in\mathcal C_{\psi,d}^{\mathrm{clf}}}D_{\mathrm{avg\text{-}bdry}}(V)\ge\frac{\delta_*}{2}.
\label{eq:app-acc-stochastic-geometry-input}
\end{equation}
The choice of \(h_*\) in~\eqref{eq:app-stoch-accuracy-amplitude-budget} gives the strict limiting amplitude gap
\begin{equation}
\mathsf a(h_*)>\mathsf b(\delta_*/2),
\label{eq:app-acc-stochastic-amplitude-gap}
\end{equation}
where \(\mathsf a\) and \(\mathsf b\) are defined in~\eqref{eq:app-acc-limiting-amplitudes}.

Choose fixed constants \(0<b<a\) such that
\begin{equation}
\mathsf b(\delta_*/2)<b<a<\mathsf a(h_*).
\label{eq:app-stoch-fixed-amplitude-gap}
\end{equation}
On \(\mathcal R_d\), the radial deviation and coherence in~\eqref{eq:app-acc-radial-coherence} converge to zero under a deterministic envelope. Therefore, for every sufficiently large \(d\), the finite-dimensional amplitudes in~\eqref{eq:app-acc-row-amplitude}--\eqref{eq:app-acc-competitor-amplitude} satisfy
\[
A_d\ge a,\qquad B_d\le b
\]
for the Row family and each of the two competitor families. Proposition~\ref{prop:app-acc-finite-bounds} consequently gives
\begin{equation}
\sup_{U\in\mathcal R_d^{\mathrm{clf}}}\mathcal E_{\pi,d}(U)\le(k-1)\overline\Phi\!\left(\frac{a}{\sigma_d}\right),
\qquad
\inf_{V\in\mathcal C_{\psi,d}^{\mathrm{clf}}}\mathcal E_{\pi,d}(V)\ge2\pi_{\min,d}\overline\Phi\!\left(\frac{b}{\sigma_d}\right).
\label{eq:app-stoch-family-error-bounds}
\end{equation}
For \(x\ge y\ge0\), the Gaussian upper tail satisfies \(\overline\Phi(x)/\overline\Phi(y)\le\exp(-(x^2-y^2)/2)\). Hence \(k=O(d)\), \(r_{\mathrm{te}}\le r_{\mathrm{te},0}\), and \(\log(1/\pi_{\min,d})=o(d)\) imply
\begin{equation}
\frac{\sup_{U\in\mathcal R_d^{\mathrm{clf}}}\mathcal E_{\pi,d}(U)}{\inf_{V\in\mathcal C_{\psi,d}^{\mathrm{clf}}}\mathcal E_{\pi,d}(V)}
\le
\frac{Ck}{\pi_{\min,d}}e^{-cd}
\longrightarrow0.
\label{eq:app-stoch-family-error-ratio}
\end{equation}
Hence, for every sufficiently large \(d\) on \(\mathcal H_d\),
\begin{equation}
\sup_{U\in\mathcal U_{\mathrm{row},\beta,b}^X}\mathcal E_{\pi,d}(U)
<
\min_{\psi\in\{\mathrm{sp},\max\}}
\inf_{V\in\mathcal U_{\psi,\beta,b}^X}\mathcal E_{\pi,d}(V).
\label{eq:app-stoch-set-error-order}
\end{equation}

It remains to transfer the set ordering to the optimizer trajectories. Proposition~\ref{prop:app-stoch-near-geometry} ensures that all effective margins are positive. Corollary~\ref{cor:app-ga-margin-transfer} therefore gives
\begin{align}
d_{\cos}\!\left(W_t^{\mathrm{RR\text{-}RowSGDM}},\mathcal U_{\mathrm{row},\beta,b}^X\right)&\longrightarrow0,\nonumber\\
d_{\cos}\!\left(W_t^{\mathrm{RR\text{-}Muon}},\mathcal U_{\mathrm{sp},\beta,b}^X\right)&\longrightarrow0,\nonumber\\
d_{\cos}\!\left(W_t^{\mathrm{RR\text{-}Signum}},\mathcal U_{\max,\beta,b}^X\right)&\longrightarrow0.
\label{eq:app-stoch-trajectory-near-set}
\end{align}
Applying Lemma~\ref{lem:app-acc-trajectory-continuity} to~\eqref{eq:app-stoch-trajectory-near-set} and then using~\eqref{eq:app-stoch-set-error-order} gives, for each \(\mathrm{opt}\in\{\mathrm{RR\text{-}Muon},\mathrm{RR\text{-}Signum}\}\),
\begin{align}
\limsup_{t\to\infty}\mathcal E_{\pi,d}\!\left(W_t^{\mathrm{RR\text{-}RowSGDM}}\right)
&\le
\sup_{U\in\mathcal U_{\mathrm{row},\beta,b}^X}\mathcal E_{\pi,d}(U)\nonumber\\
&<
\inf_{V\in\mathcal U_{\psi_{\mathrm{opt}},\beta,b}^X}\mathcal E_{\pi,d}(V)\nonumber\\
&\le
\liminf_{t\to\infty}\mathcal E_{\pi,d}\!\left(W_t^{\mathrm{opt}}\right),
\label{eq:app-stoch-trajectory-error-order}
\end{align}
where \(\psi_{\mathrm{Muon}}=\psi_{\mathrm{sp}}\) and \(\psi_{\mathrm{Signum}}=\psi_{\max}\). Since \(\operatorname{Acc}_{\pi,d}=1-\mathcal E_{\pi,d}\),
\[
\liminf_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{RR\text{-}RowSGDM}}\right)
>
\max_{\mathrm{opt}\in\{\mathrm{RR\text{-}Muon},\mathrm{RR\text{-}Signum}\}}
\limsup_{t\to\infty}\operatorname{Acc}_{\pi,d}\!\left(W_t^{\mathrm{opt}}\right).
\]
Since \(H_d\) and the dimension threshold above are independent of \(\beta\in[\beta_0,1)\), and the random-reshuffling margin bounds hold deterministically for every reshuffling realization, the conclusion holds simultaneously for all such \(\beta\) and every realization of the reshuffling.
Together with~\eqref{eq:app-stoch-accuracy-event}, this proves~\eqref{eq:stoch-optimizer-accuracy-order-clean}.

\label{lem:app-rr-adamproxy-batch-package}
Assume \(1\le b<N\). For \(z=(z_1,\ldots,z_N)\in\mathbb R^N\), define \(T_Bz:=b^{-1}\sum_{n\in B}z_n\) and \(\sigma(z)^2:=\mathbb E_B[(T_Bz)^2]\). Then
\begin{equation}
\mathbb E_B[T_Bz]=\frac1N\sum_{n=1}^Nz_n,
\label{eq:app-rr-adamproxy-batch-first-moment}
\end{equation}
\begin{equation}
\sigma(z)^2=\frac{b-1}{bN(N-1)}\left(\sum_{n=1}^Nz_n\right)^2+\frac{N-b}{bN(N-1)}\sum_{n=1}^Nz_n^2.
\label{eq:app-rr-adamproxy-batch-second-moment}
\end{equation}
Consequently, with \(\mu_1(W):=\mathbb E_B[G_B(W)]\) and \(\mu_2(W):=\mathbb E_B[G_B(W)^{\odot2}]\),
\begin{equation}
\mu_1(W)=\frac1N S(W),\qquad \mu_2(W)=\frac{(b-1)S(W)^{\odot2}+(N-b)Q(W)}{bN(N-1)},
\label{eq:app-rr-adamproxy-batch-moments-matrix}
\end{equation}
and therefore
\begin{equation}
\mu_1(W)\oslash\mu_2(W)^{\odot1/2}=\Phi_{N,b}(W).
\label{eq:app-rr-adamproxy-batch-law-direction}
\end{equation}
Moreover, because \(1\le b<N\), \(\sigma\) is a norm and
\begin{equation}
\underline c_{N,b}\|z\|_2\le\sigma(z)\le\frac1{\sqrt b}\|z\|_2,\qquad \underline c_{N,b}:=\sqrt{\frac{N-b}{bN(N-1)}},
\label{eq:app-rr-adamproxy-sigma-equivalence}
\end{equation}
while every \(b\)-subset satisfies
\begin{equation}
|T_Bz|\le K_{N,b}\sigma(z),\qquad \frac1b\sum_{n\in B}|z_n|\le K_{N,b}\sigma(z),\qquad K_{N,b}:=\sqrt{\frac{N(N-1)}{N-b}}.
\label{eq:app-rr-adamproxy-relative-batch-bound}
\end{equation}
For a matrix coordinate \(\rho=(r,a)\), define \(z_n^\rho(W):=g_n(W)[\rho]\) and \(\sigma_\rho(W):=\sigma(z^\rho(W))\). Under the nonzero-coordinate assumption in Proposition~\ref{thm:rr-adamproxy-epoch-high-memory}, \(\sigma_\rho(W)>0\) for every finite \(W\) and every \(\rho\).

\label{lem:app-rr-adamproxy-step-stability}
Let \(0<\beta_1\le\beta_2<1\) and define
\begin{equation}
A(\beta_1,\beta_2)^2:=\frac{(1-\beta_1)^2}{(1-\beta_2)(1-\beta_1^2/\beta_2)}.
\label{eq:app-rr-adamproxy-ratio-constant}
\end{equation}
Then \(\beta_1^2<\beta_2\), and for \(U_t:=M_{t+1}\oslash V_{t+1}^{\odot1/2}\),
\begin{equation}
\|U_t\|_{\max}\le A(\beta_1,\beta_2),\qquad \|W_{t+1}-W_t\|_{\mathrm F}\le\sqrt{kd}\,A(\beta_1,\beta_2)\eta_t.
\label{eq:app-rr-adamproxy-step-bound}
\end{equation}
There are finite data-dependent constants \(L,C\) such that, for all \(U,W\), every batch \(B\), and every coordinate \(\rho\),
\begin{equation}
\frac{|G_B(U)[\rho]-G_B(W)[\rho]|}{\sigma_\rho(W)}\le C\left(e^{L\|U-W\|_{\mathrm F}}-1\right),
\label{eq:app-rr-adamproxy-batch-stability}
\end{equation}
\begin{equation}
\frac{|G_B(U)[\rho]^2-G_B(W)[\rho]^2|}{\sigma_\rho(W)^2}\le C\left(e^{2L\|U-W\|_{\mathrm F}}-1\right).
\label{eq:app-rr-adamproxy-square-stability}
\end{equation}

\label{lem:app-rr-adamproxy-ema-concentration}
For every \(\delta>0\), there exists \(\omega_\delta:(0,1)\to[0,1]\) with \(\omega_\delta(\beta)\to0\) as \(\beta\uparrow1\) such that, for every epoch start \(\tau=rm\),
\begin{equation}
\mathbb P\left(\max_{0\le s<m}\sup_{z\ne{\mathbf 0}}\left|(1-\beta)\sum_{j=0}^\infty\beta^j\left(Y_{\tau+s-j}(z)-\mathbb EY_0(z)\right)\right|>\delta\right)\le\omega_\delta(\beta).
\label{eq:app-rr-adamproxy-ema-first}
\end{equation}
The same statement holds with \(Y_t(z)^2\) in place of \(Y_t(z)\) and \(\mathbb E[Y_0(z)^2]=1\). For fixed \(N,b\), one may take \(\omega_\delta(\beta)\le C_\delta(1-\beta)\).

\label{lem:app-rr-adamproxy-freezing}
Fix \(0<\beta_1\le\beta_2<1\). Under the assumptions of Proposition~\ref{thm:rr-adamproxy-epoch-high-memory}, for every coordinate \(\rho\), uniformly over \(0\le s<m\),
\begin{equation}
\frac{|M_{\tau_r+s+1}[\rho]-\overline M_{\tau_r+s}^{\beta_1}(W_{\tau_r})[\rho]|}{\sigma_\rho(W_{\tau_r})}\xrightarrow[r\to\infty]{\mathbb P}0,
\label{eq:app-rr-adamproxy-freezing-first}
\end{equation}
\begin{equation}
\frac{|V_{\tau_r+s+1}[\rho]-\overline V_{\tau_r+s}^{\beta_2}(W_{\tau_r})[\rho]|}{\sigma_\rho(W_{\tau_r})^2}\xrightarrow[r\to\infty]{\mathbb P}0.
\label{eq:app-rr-adamproxy-freezing-second}
\end{equation}
The convergence is uniform over the finitely many coordinates.

\label{lem:app-rr-adamproxy-ratio-continuity}
There is a universal \(C_{\mathrm{rat}}<\infty\) such that, whenever \(\sigma>0\), \(|a_0|\le\sigma\), \(|a-a_0|\le\delta\sigma\), and \(|v-\sigma^2|\le\delta\sigma^2\) with \(0<\delta\le1/2\),
\begin{equation}
\left|\frac a{\sqrt v}-\frac{a_0}{\sigma}\right|\le C_{\mathrm{rat}}\delta.
\label{eq:app-rr-adamproxy-ratio-continuity}
\end{equation}

Let \(f_{N,b}(W):=\mu_1(W)\oslash\mu_2(W)^{\odot1/2}=\Phi_{N,b}(W)\) by Lemma~\ref{lem:app-rr-adamproxy-batch-package}. Because the Adam update uses the gradient convention,
\begin{equation}
\frac{W_{\tau_r+m}-W_{\tau_r}}{\gamma_r}=-\sum_{s=0}^{m-1}\frac{\eta_{\tau_r+s}}{\gamma_r}U_{\tau_r+s},\qquad \sum_{s=0}^{m-1}\frac{\eta_{\tau_r+s}}{\gamma_r}=1.
\label{eq:app-rr-adamproxy-epoch-displacement}
\end{equation}
Fix \(0<\delta\le1/4\). Lemma~\ref{lem:app-rr-adamproxy-ema-concentration} gives, with probability at least \(1-\omega_\delta(\beta_1)-\omega_\delta(\beta_2)\), relative \(\delta\)-control of both frozen memories around \(\mu_1(W_{\tau_r})\) and \(\mu_2(W_{\tau_r})\), simultaneously over the epoch and all coordinates. Lemma~\ref{lem:app-rr-adamproxy-freezing} transfers these bounds to the actual memories with \(2\delta\) in place of \(\delta\), up to an event whose probability vanishes as \(r\to\infty\). Jensen's inequality gives \(|\mu_1(W)[\rho]|\le\sqrt{\mu_2(W)[\rho]}=\sigma_\rho(W)\), so Lemma~\ref{lem:app-rr-adamproxy-ratio-continuity} yields
\begin{equation}
\max_{0\le s<m}\|U_{\tau_r+s}-\Phi_{N,b}(W_{\tau_r})\|_{\max}\le C\delta
\label{eq:app-rr-adamproxy-stepwise-proxy-bound}
\end{equation}
with the same asymptotic probability. Combining \eqref{eq:app-rr-adamproxy-epoch-displacement} and \eqref{eq:app-rr-adamproxy-stepwise-proxy-bound} gives
\begin{equation}
\left\|\frac{W_{\tau_r+m}-W_{\tau_r}}{\gamma_r}+\Phi_{N,b}(W_{\tau_r})\right\|_{\max}\le C\delta.
\label{eq:app-rr-adamproxy-epoch-proxy-bound}
\end{equation}
Given \(\varepsilon>0\), choose \(\delta\) so that \(C\delta<\varepsilon\). Taking \(r\to\infty\) first yields a limsup probability bounded by \(\omega_\delta(\beta_1)+\omega_\delta(\beta_2)\), and then taking \((\beta_1,\beta_2)\to(1,1)\) through \(0<\beta_1\le\beta_2<1\) proves \eqref{eq:rr-adamproxy-one-epoch-limit-clean}.

\label{prop:app-adamproxy-boundary-separation}
For every sufficiently large \(d\), on the event \(\mathcal E_d^{\mathrm{near}}\) from Lemma~\ref{lem:app-stoch-combined-input}, the AdamProxy trajectory satisfies
\begin{equation}
\frac{W_t^{\mathrm{AP}}}{\operatorname{mar}_X(W_t^{\mathrm{AP}})}\in\mathcal C_d\qquad\text{for all sufficiently large }t,
\label{eq:app-adamproxy-eventual-capped-membership}
\end{equation}
and
\begin{equation}
\inf_{V\in\mathcal C_d}\min_{i\ne j}\|u_{ij}^V-u_{ij}^{\mu}\|_2\ge\delta_{\mathrm{AP}}-o_d(1).
\label{eq:app-adamproxy-boundary-separation}
\end{equation}
The error is deterministic on \(\mathcal E_d^{\mathrm{near}}\) and uniform over \(V\in\mathcal C_d\).
The time threshold in \eqref{eq:app-adamproxy-eventual-capped-membership} may depend on the dimension, dataset, initialization, and learning-rate schedule.

\label{lem:app-adamproxy-row-control}
For every fixed \(\beta\in[\beta_{\mathrm{AP}},1)\), on \(\mathcal E_d^{\mathrm{near}}\) and for every sufficiently large \(d\), the RR-RowSGDM effective margin is positive and
\begin{equation}
\sup_{U\in\mathcal U_{\mathrm{row},\beta,b_d}^X}\max_{i\ne j}\|u_{ij}^U-u_{ij}^{\mu}\|_2\le h_{\mathrm{AP}}.
\label{eq:app-adamproxy-row-control}
\end{equation}

The remainder of this subsection proves Proposition~\ref{thm:adamproxy-margin-clean}. We first rewrite the AdamProxy dynamics in terms of descent signals and normalized wrong-class coefficients, then characterize the trajectory-selected limiting coefficients, and finally verify the primal--dual optimality conditions of the quadratic margin problem.

Define the descent signals
\begin{equation}
h_n(W):=-g_n(W)=(e_{y_n}-p_n(W))x_n^\top,
\label{eq:app-adamproxy-descent-signal}
\end{equation}
and write \(A_{n,c}:=(e_{y_n}-e_c)x_n^\top\) for \((n,c)\in\mathcal Q\). Then \(h_n(W)=\sum_{c\ne y_n}p_{n,c}(W)A_{n,c}\). Set
\begin{equation}
\widetilde S(W):=\sum_{n=1}^Nh_n(W)=-S(W),\qquad \widetilde Q(W):=\sum_{n=1}^Nh_n(W)^{\odot2}=Q(W).
\label{eq:app-adamproxy-descent-SQ}
\end{equation}






For \(\theta\in\Delta(\mathcal Q)\), write
\begin{equation}
\begin{aligned}
\mathsf S(\theta)&:=\sum_{n=1}^NZ_n(\theta),\qquad \mathsf Q(\theta):=\sum_{n=1}^NZ_n(\theta)^{\odot2}, \\ \mathsf D_{N,b}(\theta)&:=\left(\frac{N}{b(N-1)}\left((b-1)\mathsf S(\theta)^{\odot2}+(N-b)\mathsf Q(\theta)\right)\right)^{\odot1/2}.
\label{eq:app-adamproxy-SQ-theta}
\end{aligned}
\end{equation}
Thus \(M_{N,b}(\theta)=\operatorname{diag}(\operatorname{vec}\mathsf D_{N,b}(\theta))\). Define
\begin{equation}
\Psi_{N,b}(W):=\widetilde S(W)\oslash\left(\frac{N}{b(N-1)}\left((b-1)\widetilde S(W)^{\odot2}+(N-b)\widetilde Q(W)\right)\right)^{\odot1/2},
\label{eq:app-adamproxy-descent-proxy-relation}
\end{equation}
with \(0/0:=0\) entrywise. The explicit proxy formula in the main text gives \(\Psi_{N,b}(W)=-\Phi_{N,b}(W)\), so the AdamProxy dynamics can be written as \(W_{t+1}^{\mathrm{AP}}=W_t^{\mathrm{AP}}+\gamma_t\Psi_{N,b}(W_t^{\mathrm{AP}})\).





\begin{lemma}[Coefficient representation and trajectory-selected limit]
\label{lem:app-adamproxy-selected-limit}
For finite \(W\), define
\begin{equation}
R(W):=\sum_{(n,c)\in\mathcal Q}p_{n,c}(W)>0,\qquad \theta_{n,c}(W):=\frac{p_{n,c}(W)}{R(W)}.
\label{eq:app-adamproxy-theta}
\end{equation}
Then
\begin{equation}
h_n(W)=R(W)Z_n(\theta(W)),\qquad \widetilde S(W)=R(W)\mathsf S(\theta(W)),\qquad \widetilde Q(W)=R(W)^2\mathsf Q(\theta(W)),
\label{eq:app-adamproxy-coefficient-factorization}
\end{equation}
\begin{equation}
\Psi_{N,b}(W)=\mathsf S(\theta(W))\oslash\mathsf D_{N,b}(\theta(W)),\qquad \|\Psi_{N,b}(W)\|_{\max}\le1.
\label{eq:app-adamproxy-coefficient-proxy}
\end{equation}
Under the assumptions of Proposition~\ref{thm:adamproxy-margin-clean},
\begin{equation}
\frac{W_t^{\mathrm{AP}}}{\|W_t^{\mathrm{AP}}\|_{\mathrm F}}\longrightarrow\overline W:=-\overline\Phi,
\label{eq:app-adamproxy-Wbar-sign}
\end{equation}
and there exist a subsequence \(t_j\to\infty\), \(\theta^\star\in\Delta(\mathcal Q)\), and \(\nu\in(0,\infty)\) such that
\begin{equation}
\theta(W_{t_j}^{\mathrm{AP}})\to\theta^\star,\qquad \|\Psi_{N,b}(W_{t_j}^{\mathrm{AP}})\|_{\mathrm F}\to\nu,\qquad \Psi_{N,b}(W_{t_j}^{\mathrm{AP}})\to\nu\overline W,
\label{eq:app-adamproxy-selected-subsequence}
\end{equation}
with \(\mathsf S(\theta^\star)\ne{\mathbf 0}\) and \(\nu\|\overline W\|_{\max}\le1\).
\end{lemma}


\begin{proof}
The factorization follows directly from \(h_n(W)=\sum_{c\ne y_n}p_{n,c}(W)A_{n,c}\). For every coordinate \(\rho\), Cauchy--Schwarz gives \(\mathsf S(\theta)[\rho]^2\le N\mathsf Q(\theta)[\rho]\), and therefore
\[
\mathsf D_{N,b}(\theta)[\rho]^2-\mathsf S(\theta)[\rho]^2=\frac{N-b}{b(N-1)}\left(N\mathsf Q(\theta)[\rho]-\mathsf S(\theta)[\rho]^2\right)\ge0.
\]
Hence \(\mathsf D_{N,b}(\theta)[\rho]\ge|\mathsf S(\theta)[\rho]|\), and if \(\mathsf D_{N,b}(\theta)[\rho]=0\), then \(\mathsf S(\theta)[\rho]=0\). With the convention \(0/0:=0\), this proves \eqref{eq:app-adamproxy-coefficient-proxy} and the coordinate bound. By linear separability, choose \(V\) and \(\sigma_{\mathrm{sep}}>0\) with \(\langle V,A_q\rangle\ge\sigma_{\mathrm{sep}}\) for every \(q\). Since \(\mathsf D_{N,b}\) is continuous on the compact simplex, \(D_{\max}:=\max_\theta\|\mathsf D_{N,b}(\theta)\|_{\max}<\infty\), and
\[
\sigma_{\mathrm{sep}}\le\langle V,\mathsf S(\theta(W))\rangle\le\|V\|_{\mathrm F}D_{\max}\|\Psi_{N,b}(W)\|_{\mathrm F}.
\]
Thus \(\|\Psi_{N,b}(W_t)\|_{\mathrm F}\) is bounded above and below by positive constants. Since \(\Psi_{N,b}(W)=-\Phi_{N,b}(W)\), the normalized descent-proxy directions satisfy \(\Psi_{N,b}(W_t)/\|\Psi_{N,b}(W_t)\|_{\mathrm F}\to-\overline\Phi\). Assumption~\ref{ass:lr-base} implies that the epochwise schedule \(\gamma_t\) is positive, tends to zero, and satisfies \(\sum_t\gamma_t=\infty\). With \(T_t:=\sum_{s=0}^{t-1}\gamma_s\|\Psi_{N,b}(W_s)\|_{\mathrm F}\), one has \(T_t\to\infty\) and
\[
\frac{W_t}{T_t}=\frac{W_0}{T_t}+\frac1{T_t}\sum_{s=0}^{t-1}\gamma_s\|\Psi_{N,b}(W_s)\|_{\mathrm F}\frac{\Psi_{N,b}(W_s)}{\|\Psi_{N,b}(W_s)\|_{\mathrm F}}\longrightarrow-\overline\Phi.
\]
Hence \(\|W_t\|_{\mathrm F}/T_t\to1\) and \(W_t/\|W_t\|_{\mathrm F}\to-\overline\Phi\), proving \eqref{eq:app-adamproxy-Wbar-sign}. Compactness of \(\Delta(\mathcal Q)\) and the two-sided bound on \(\|\Psi_{N,b}(W_t)\|_{\mathrm F}\) give a subsequence satisfying \eqref{eq:app-adamproxy-selected-subsequence}. The separator inequality passes to the limit and gives \(\mathsf S(\theta^\star)\ne{\mathbf 0}\), while \(\|\Psi_{N,b}(W_{t_j})\|_{\max}\le1\) yields \(\nu\|\overline W\|_{\max}\le1\).
\end{proof}





\begin{proposition}[Selected stationarity and positive margin]
\label{prop:app-adamproxy-stationarity-margin}
For the limit in Lemma~\ref{lem:app-adamproxy-selected-limit}, there exists \(\alpha=\nu^{-1}>0\) such that
\begin{equation}
M_{N,b}(\theta^\star)\operatorname{vec}(\overline W)=\alpha\operatorname{vec}(\mathsf S(\theta^\star))=\alpha\sum_{q\in\mathcal Q}\theta_q^\star\operatorname{vec}(A_q).
\label{eq:app-adamproxy-selected-stationarity}
\end{equation}
Moreover,
\begin{equation}
\gamma_{\mathrm{AP}}:=\min_{q\in\mathcal Q}\langle\overline W,A_q\rangle>0,
\qquad
\operatorname{supp}(\theta^\star)\subseteq\operatorname*{arg\,min}_{q\in\mathcal Q}\langle\overline W,A_q\rangle.
\label{eq:app-adamproxy-positive-margin-support}
\end{equation}
\end{proposition}

\begin{proof}
Let \(\mathsf S^\star:=\mathsf S(\theta^\star)\) and \(\mathsf D^\star:=\mathsf D_{N,b}(\theta^\star)\). If \(\mathsf D^\star[\rho]>0\), continuity and \eqref{eq:app-adamproxy-selected-subsequence} give \(\mathsf S^\star[\rho]/\mathsf D^\star[\rho]=\nu\overline W[\rho]\). If \(\mathsf D^\star[\rho]=0\), then the inequality \(\mathsf D_{N,b}(\theta)[\rho]\ge|\mathsf S(\theta)[\rho]|\) proved above gives \(\mathsf S^\star[\rho]=0\). Hence \eqref{eq:app-adamproxy-selected-stationarity} holds on every coordinate. It also gives
\begin{equation}
\langle\overline W,\mathsf S(\theta^\star)\rangle=\nu\sum_\rho\mathsf D^\star[\rho]\overline W[\rho]^2>0.
\label{eq:app-adamproxy-positive-average}
\end{equation}
To identify the support, write \(\overline m_{n,c}:=\langle\overline W,A_{n,c}\rangle\), \(\mu_n:=\min_{c\ne y_n}\overline m_{n,c}\), and \(h_{n,c}:=\overline m_{n,c}-\min\{0,\mu_n\}\). Since \(\|W_t\|_{\mathrm F}\to\infty\) and \(W_t/\|W_t\|_{\mathrm F}\to\overline W\), finite log-sum-exp asymptotics give
\[
-\frac1{\|W_t\|_{\mathrm F}}\log p_{n,c}(W_t)\longrightarrow h_{n,c}.
\]
Therefore every subsequential limit \(\theta^\star\) is supported on the atoms minimizing \(h_{n,c}\). If some \(\mu_n\le0\), then the minimum of \(h\) is zero and every minimizing atom has \(\overline m_{n,c}\le0\), contradicting \eqref{eq:app-adamproxy-positive-average}. Thus every \(\mu_n>0\), so \(h_{n,c}=\overline m_{n,c}\), proving both claims in \eqref{eq:app-adamproxy-positive-margin-support}.
\end{proof}




For fixed \(\theta\in\Delta(\mathcal Q)\), let \(a_q:=\operatorname{vec}(A_q)\) and define
\begin{equation}
\mathcal L_\theta(u,\lambda):=\frac12u^\top M_{N,b}(\theta)u+\sum_{q\in\mathcal Q}\lambda_q(1-a_q^\top u),\qquad g_\theta(\lambda):=\inf_{u\in\mathbb R^{kd}}\mathcal L_\theta(u,\lambda),\qquad \lambda\ge0.
\label{eq:app-adamproxy-lagrangian}
\end{equation}

\begin{lemma}[Semidefinite primal-dual certificate]
\label{lem:app-adamproxy-psd-kkt}
Fix \(\theta\in\Delta(\mathcal Q)\). Suppose \(U\) is feasible for \eqref{eq:adamproxy-primal-clean} and \(\lambda\ge0\) satisfies
\begin{equation}
M_{N,b}(\theta)\operatorname{vec}(U)=\sum_{q\in\mathcal Q}\lambda_q\operatorname{vec}(A_q),\qquad \lambda_q(\langle U,A_q\rangle-1)=0\quad(q\in\mathcal Q).
\label{eq:app-adamproxy-psd-kkt}
\end{equation}
Then \(U\in\mathcal P_{N,b}(\theta)\), and \(\lambda\) is a dual optimizer. No invertibility of \(M_{N,b}(\theta)\) is required.
\end{lemma}

\begin{proof}
Write \(u:=\operatorname{vec}(U)\), \(M:=M_{N,b}(\theta)\), and let \(V\) be any feasible matrix with \(v:=\operatorname{vec}(V)\). Since \(M\succeq0\),
\[
\frac12v^\top Mv-\frac12u^\top Mu=\frac12(v-u)^\top M(v-u)+\sum_q\lambda_q\langle V-U,A_q\rangle\ge0,
\]
where feasibility and complementarity are used in the last step. Thus \(U\) is primal optimal. Stationarity makes \(u\) a global minimizer of the Lagrangian for this \(\lambda\), and complementarity makes the dual value equal the primal value, so \(\lambda\) is dual optimal by weak duality.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{thm:adamproxy-margin-clean}]
Set \(p^\star:=\overline W/\gamma_{\mathrm{AP}}\), where \(\overline W=-\overline\Phi\) and \(\gamma_{\mathrm{AP}}>0\) are given by Lemma~\ref{lem:app-adamproxy-selected-limit} and Proposition~\ref{prop:app-adamproxy-stationarity-margin}. Let \(\alpha\) be the scalar in \eqref{eq:app-adamproxy-selected-stationarity} and define
\begin{equation}
\lambda_q^\star:=\frac{\alpha}{\gamma_{\mathrm{AP}}}\theta_q^\star.
\label{eq:app-adamproxy-dual-candidate}
\end{equation}
Then \(p^\star\) is feasible because \(\langle p^\star,A_q\rangle\ge1\), and dividing \eqref{eq:app-adamproxy-selected-stationarity} by \(\gamma_{\mathrm{AP}}\) gives the stationarity equation in Lemma~\ref{lem:app-adamproxy-psd-kkt}. If \(\lambda_q^\star>0\), then \(\theta_q^\star>0\), so \eqref{eq:app-adamproxy-positive-margin-support} gives \(\langle\overline W,A_q\rangle=\gamma_{\mathrm{AP}}\) and hence complementarity. Lemma~\ref{lem:app-adamproxy-psd-kkt} therefore yields \(p^\star\in\mathcal P_{N,b}(\theta^\star)\) and dual optimality of \(\lambda^\star\). Finally,
\[
\|\lambda^\star\|_1=\frac{\alpha}{\gamma_{\mathrm{AP}}}\sum_q\theta_q^\star=\frac{\alpha}{\gamma_{\mathrm{AP}}}>0,
\]
so \(\theta^\star=\lambda^\star/\|\lambda^\star\|_1\). This proves the proposition.
\end{proof}

